schemas.schema-01-core.prisma:
/// [User Account Entity] - This implements the secure, scalable, privacy-first user management requirement from the User & Identity Management module. 
///
/// Provides foundational identities for the platform. Maintains 3NF compliance by separating identity from profile, session, and permissions. For example, links to user events, access logs, consents, and profiles. 
///
/// Key relationships: user_profiles, sessions, consents, access_logs, roles, organizations.
/// Special behaviors: usernames/emails are unique, secure credential storage, full traceability and audit logging.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model users {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each user.
  id String @id @db.Uuid

  /// Belonged organization's {@link organizations.id}. Used for multi-tenancy and B2B relationships.
  organization_id String? @db.Uuid

  /// Belonged role's {@link roles.id}. Assigns user to a role for RBAC.
  role_id String @db.Uuid

  /// [Username] - User-selected or system-generated unique username. Implements secure, unique identity requirement. For login and referencing across modules. Ensures normalization by not duplicating emails/names. Example: 'john_smith'. Unique per system.
  username String

  /// [Email Address] - Primary communication and login identifier. Implements secure user recovery and notification flow requirement. Must be unique. Example: 'user@example.com'.
  email String

  /// [Phone Number] - Optional phone, for multi-factor authentication or contact. Implements inclusive, multi-channel communication. Can be null for email-only accounts.
  phone String?

  /// [Hashed Password] - Stores strong password hash. Implements credential protection. Ensures normalization by storing only the hash (not credentials themselves) here. Never exposed via APIs.
  password_hash String

  /// [Active Status] - Whether the account is currently enabled. Implements account lifecycle management and compliance. Disabled users cannot login or perform actions. For suspension, GDPR right-to-block, etc.
  is_active Boolean

  /// [Created Timestamp] - User creation date/time. Implements audit and evidence tracking requirement. Used for onboarding analytics and compliance.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last update time for the user record. Implements integrity and audit requirement. Track for change management logs.
  updated_at DateTime @db.Timestamptz

  /// [Deletion Timestamp] - Soft delete field (nullable). Implements evidence preservation and GDPR/CCPA right-to-erasure protocols. Preserved for audit without exposing to regular queries.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  organization organizations? @relation(fields: [organization_id], references: [id], onDelete: Cascade)
  role roles @relation(fields: [role_id], references: [id], onDelete: Cascade)

  user_profiles user_profiles?
  sessions sessions[]
  consents consents[]
  access_logs access_logs[]
  products_of_created_by_user_id products[] @relation("products_of_created_by_user_id")
  products_of_updated_by_user_id products[] @relation("products_of_updated_by_user_id")
  catalog_events catalog_events[]
  cart cart[]
  order order[]
  payment_methods payment_methods[]
  transactions transactions[]
  vouchers vouchers[]
  loyalty_points loyalty_points[]
  payment_audits payment_audits[]
  message_threads message_threads[]
  messages messages[]
  notifications notifications[]
  reviews reviews[]
  review_moderations review_moderations[]
  favorites favorites[]
  bookmarks bookmarks[]
  personalization_events personalization_events[]
  recommendations recommendations[]
  personalization_audits personalization_audits[]
  ai_models ai_models[]
  ai_decision_logs ai_decision_logs[]
  ai_feedback ai_feedback[]
  security_event security_event[]
  audit_log audit_log[]
  compliance_report compliance_report[]

  @@index([role_id])

  @@unique([username])
  @@unique([email])
  @@index([organization_id, role_id])
  @@index([created_at])
}

/// [User Profile Entity] - This implements the extended user attributes and multicultural/accessibility requirements. 
///
/// Contains personal information, preferences, localization, and accessibility settings, attached 1:1 to a user. Maintains 3NF by separating profile from credential and account data. Example: stores names, avatars, language, timezone, accessibility options. 
///
/// Key relationships: users (required), locales (optional).
/// Special behaviors: Only one profile per user, enforces privacy segregation from authentication data.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model user_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique profile record.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. 1:1 with users for privacy and structure.
  user_id String @db.Uuid

  /// Linked locale's {@link locales.id}. Assigns preferred language/region to user.
  locale_id String? @db.Uuid

  /// [Full Name] - Implements user's display identity requirement. For greetings, notification, and accessibility. Can be null if user prefers pseudonymity. Not duplicated elsewhere (3NF compliant). Example: 'Jane Doe'.
  full_name String?

  /// [Avatar URI] - User's avatar/profile image URI. Implements personalization and a11y requirement. Example: 'https://...'
  avatar_url String? @db.VarChar(80000)

  /// [Timezone] - User's timezone code/setting. Ensures correct time display throughout platform. Implements accessibility and multicultural flow. Example: 'Asia/Seoul'.
  timezone String?

  /// [Bio] - Optional short biography or profile info for personalization. Implements user engagement. May be null. Example: 'Brand marketer and cat lover.'
  bio String?

  /// [Accessibility Preferences] - Stores serialized config for accessibility (screen reader, high contrast, etc). Implements accessibility compliance. 3NF: Not duplicated in any other place. Null if not set.
  a11y_prefs String?

  /// [Created Timestamp] - Profile creation date/time. Evidence and audit. For analytics, onboarding timelines, and compliance.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last update to this profile. Audit trail and compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)
  locale locales? @relation(fields: [locale_id], references: [id], onDelete: Cascade)

  @@unique([user_id])
  @@index([locale_id])
  @@index([full_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Organization Entity] - This implements the multi-tenancy and B2B compliance requirement. 
///
/// Represents a logical business or retailer, to whom users, roles, resources may belong. Maintains 3NF: organization details are not repeated elsewhere. Supports future expansion for B2B, partner, and omnichannel flows. 
///
/// Key relationships: users, roles. 
/// Special behaviors: names/codes are unique within system.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model organizations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique org record.
  id String @id @db.Uuid

  /// [Organization Name] - The display/legal name for this org. Enforces multi-tenancy boundaries. Example: 'Acme Corp'. Unique system-wide.
  name String

  /// [Organization Code] - Short unique code/slug. Used for B2B/APIs. Example: 'ACMEC'. Ensures normalization: not repeated elsewhere. Unique.
  code String

  /// [Created Timestamp] - Org creation date/time. Audit, analytics, compliance.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last update to record. Audit and compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  users users[]
  roles roles[]
  ai_models ai_models[]
  compliance_report compliance_report[]
  data_retention data_retention[]

  @@unique([name])
  @@unique([code])
}

/// [Role Entity] - Implements RBAC requirement for user access and multi-tenant permissioning. 3NF by separating roles from users. 
///
/// Defines named permission sets assignable to users (e.g. 'admin', 'retailer', 'customer'). 
///
/// Key relationships: users, organizations (optional).
/// Special behaviors: names/codes unique per org (composite uniqueness).
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model roles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged organization's {@link organizations.id}. Allows role scoping.
  organization_id String? @db.Uuid

  /// [Role Name] - Human-readable display name for the role. Example: 'admin', 'editor', 'customer'. Unique per org. Not duplicated in user records (3NF).
  name String

  /// [Role Code] - Machine code/slug. Used in policies/APIs. Example: 'ADMIN'. Unique per org.
  code String

  /// [Role Description] - Explanation of permissions/responsibilities. Used in admin UI. Example: 'Super administrator with all rights.'
  description String?

  /// [Created Timestamp] - Record creation time. Evidence, audit, analytics.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last update to record. Compliance, change history.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  organization organizations? @relation(fields: [organization_id], references: [id], onDelete: Cascade)

  users users[]

  @@unique([organization_id, name])
  @@unique([organization_id, code])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [User Session Entity] - Implements authentication/session management for security and compliance. 
///
/// Tracks logins, MFA status, device fingerprints, and session validity for users. Maintains 3NF: session metadata separate from account/profile data. 
///
/// Key relationships: users (required).
/// Special behaviors: token is unique, enables forced logout, auditing of login locations/devices.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique session ID.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Session always tied to a single user.
  user_id String @db.Uuid

  /// [Session Token] - Opaque token identifying current session (may be JWT or random). Not user credential. Unique per session, never duplicated. Used for cookie/API authentication.
  token String

  /// [Expiration] - Timestamp this session expires. Used for timeout/logout. Enforces compliance (GDPR) and security (idle timeout).
  expires_at DateTime @db.Timestamptz

  /// [Device Fingerprint] - Optional device identifier for fraud prevention/MFA. Supports AI-driven risk flagging. Null if unknown device.
  device_fingerprint String?

  /// [IP Address] - Last known IP address (logins/requests). Used for analytics and fraud detection. May be IPv4 or v6.
  ip String?

  /// [Created Timestamp] - When session was created. For session analytics, compliance, and security logging.
  created_at DateTime @db.Timestamptz

  /// [Revocation Timestamp] - Soft delete for session termination/logouts/compromised. Audit, compliance. Null if active.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  access_logs access_logs[]
  cart cart[]
  security_event security_event[]

  @@unique([token])
  @@index([user_id])
}

/// [Locale Entity] - Implements multilingual/multicultural and accessibility support, required for I18N/L10N. 
///
/// Defines available language/region options across platform. Maintains 3NF by centralizing locales. 
///
/// Key relationships: user_profiles.
/// Special behaviors: code is unique, supports expansion without refactoring user records.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model locales {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique locale record.
  id String @id @db.Uuid

  /// [Locale Code] - BCP 47 code for locale/language-region. Example: 'en-US', 'ko-KR'. Used for runtime and user preference mapping. Not duplicated elsewhere. Unique.
  code String

  /// [Locale Name] - Human display name, e.g., 'English (United States)'. Used in UIs and reporting. Not duplicated (3NF).
  name String

  //----
  // RELATIONS
  //----
  user_profiles user_profiles[]

  @@unique([code])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Consent Entity] - Implements regulatory consent management and audit tracking for user data access, AI/ML operations, and data subject rights. 
///
/// Each record logs explicit user permission (for data use, AI training, communication, etc.), with retention and audit status. Maintains 3NF by storing consents independently. 
///
/// Key relationships: users (required).
/// Special behaviors: unique per (user, type), critical evidence for compliance and explainability.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model consents {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique consent record.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Each consent is linked to a user.
  user_id String @db.Uuid

  /// [Consent Type] - What the consent is for (e.g., 'ai_training', 'marketing', 'data_sharing'). Implements regulatory granularity and traceability. Unique per user/type.
  type String

  /// [Is Granted] - Whether consent is currently active. Implements GDPR/CCPA protocol. Example: true for opt-in, false for opt-out.
  is_granted Boolean

  /// [Granted Timestamp] - Date/time consent granted. For audit/EVIDENCE preservation.
  granted_at DateTime @db.Timestamptz

  /// [Revoked Timestamp] - Date/time consent was revoked (nullable). For lifecyle tracking, right-to-forget, compliance.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([user_id, type])
}

/// [Access Log Entity] - Implements immutable, evidence-grade session/access tracking for compliance, audit, and AI/ML profiling. 3NF: links to users, sessions, and records every access event with unique context. 
///
/// Key relationships: users (required), sessions (optional). 
/// Special behaviors: all field values atomic and granular, no pre-aggregation; log is append-only.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model access_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique access log record.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Required for every access event.
  user_id String @db.Uuid

  /// Belonged session's {@link sessions.id}. Tracks which authenticated session (if any) was used for this event. Nullable for service/system access.
  session_id String? @db.Uuid

  /// [Event Type] - Type of access (e.g. 'login', 'logout', 'api_call'). Atomic (3NF), used for filtering/analytics.
  event_type String

  /// [IP Address] - Originating IP of the request. Required for security analytics, fraud detection. 3NF: not duplicated in session/user, always present here.
  ip String

  /// [User Agent] - Client software/device string for the request. Key for security/audit analytics. This is atomic and not pre-processed; always stored in full.
  agent String

  /// [Success Flag] - Whether the access event resulted in successful authentication or action. Key compliance/audit outcome tracker.
  success Boolean

  /// [Occurred At] - Exact timestamp of the access event (UTC). Preserved for forensic/audit/analytics evidence. Never updated/overwritten (append-only log).
  occurred_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)
  session sessions? @relation(fields: [session_id], references: [id], onDelete: Cascade)

  @@index([session_id])

  @@index([user_id, occurred_at])
}

schemas.schema-02-product_catalog.prisma:
/// Product entity - This implements the formal Product definition requirement from the requirements analysis. 
///
/// Defines a distinct, master product in the catalog. Supports lifecycle, multilingual data, AI tagging, and event evidence. Maintains 3NF compliance by separating variants, media, and relationships into normalized tables, with history/audit built via catalog_event. For example, 'Nike Air Max 2025' is a product with multiple variants, multilingual names, and tags.
///
/// Key relationships: variants (product_variants), categories (product_categories), media (product_media), AI tagging/relations, evidence chain (catalog_evidence).
/// Special behaviors: No calculated fields; state managed via events. Tags and categories are many-to-many via join tables.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model products {
  //----
  // COLUMNS
  //----
  /// Primary Key. Globally unique product identifier.
  id String @id @db.Uuid

  /// Creator's user {@link users.id}. Maintains authorship, compliance, and access tracking.
  created_by_user_id String @db.Uuid

  /// Last updater's user {@link users.id}. Maintains modification tracking and audit compliance.
  updated_by_user_id String @db.Uuid

  /// Product canonical name - Implements the core product naming requirement.
  ///
  /// Atomic field, supports primary search/display. Eg: 'Apple iPhone 23'. Normalized (no composite names).
  name String

  /// Localized/language-variant product description. Represents main product overview.
  ///
  /// Supports i18n by being atomic; per-language splits handled in separate table if needed. Eg: short English/long Korean text.
  description String

  /// Internal code/identifier for supply chain tracking (SKU-less, human-readable).
  ///
  /// Fully atomic value, no lookups. Eg: 'PROD-2025-AX1'.
  internal_code String

  /// Logical product state (draft, active, suspended, archived) - Implements state machine requirement.
  ///
  /// Atomic value used for workflow/status handling. Eg: 'active'. No transitive dependencies.
  status String

  /// Creation timestamp. Implements data logging, compliance, catalog event lifecycle.
  ///
  /// Atomic. Not calculated; audit enforced via event log.
  created_at DateTime @db.Timestamptz

  /// Most recent update timestamp. Audit/compliance/log requirement. Atomic and independent of other fields.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  creator users @relation("products_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updater users @relation("products_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  product_variants product_variants[]
  product_options product_options[]
  product_media product_media[]
  catalog_events catalog_events[]
  reviews reviews[]
  favorites favorites[]
  bookmarks bookmarks[]
  personalization_events personalization_events[]
  recommendations recommendations[]

  @@index([created_by_user_id])
  @@index([updated_by_user_id])

  @@unique([internal_code])
  @@index([status])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product variant entity - This implements the variant granularity and stock/SKU separation requirement.
///
/// Represents a specific salable shape of a master product. Fully normalized (3NF) by separating each variant's attributes and price/inventory from the parent product. For example, 'Nike Air Max 2025, Size 10, Red'.
///
/// Key relationships: belongs to a product, links to inventory, options, and import feeds for external sync.
/// Special behaviors: No calculated fields; prices are absolute values. Tracks provenance via import_feed_id if imported.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique variant identifier.
  id String @id @db.Uuid

  /// Parent product's {@link products.id} - Enforces variant dependence.
  product_id String @db.Uuid

  /// Import source feed's {@link import_feeds.id}. For data provenance, nullable if direct.
  import_feed_id String? @db.Uuid

  /// SKU for the variant (external or internal) - Implements inventory and supply chain reference, atomic per variant.
  sku String

  /// Unit price for the stock-keeping unit; monetary value in store currency.
  ///
  /// No pre-calculation, represents current/active price only.
  price Float @db.DoublePrecision

  /// Retail barcode or EAN for regulatory scan/stock management. Atomic, not combined.
  barcode String

  /// Denotes if variant is enabled for sale. Atomic flag, not calculated.
  available Boolean

  /// Timestamp of variant creation. Supports event/audit compliance, atomic value.
  created_at DateTime @db.Timestamptz

  /// Last modification of the variant; atomic, tracked for compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product products @relation(fields: [product_id], references: [id], onDelete: Cascade)
  import_feed import_feeds? @relation(fields: [import_feed_id], references: [id], onDelete: Cascade)

  product_media product_media[]
  inventory inventory?
  catalog_events catalog_events[]
  cart_item cart_item[]
  order_item order_item[]

  @@unique([sku])
  @@index([product_id])
  @@index([import_feed_id])
}

/// Product category entity - This implements the taxonomy and product grouping requirement.
///
/// Represents a single normalized category. 3NF adherence by separating parent/child via parent_id; supports multi-level category trees. Used for faceted navigation and analytics. E.g., 'Shoes', 'Sneakers', 'Men's Running'.
///
/// Key relationships: parent/child self-reference, mapping to products (many-to-many) via join table.
/// Special behaviors: Cannot be deleted if in use (application-level rule).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model product_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique category identifier.
  id String @id @db.Uuid

  /// Parent category id {@link product_categories.id} (for hierarchy); nullable for root.
  parent_id String? @db.Uuid

  /// Category display name; atomic. E.g.: 'Apparel', 'Running Shoes'.
  name String

  /// Category creation timestamp, for logging, evidence, and i18n flows.
  created_at DateTime @db.Timestamptz

  /// Category update timestamp. Maintains audit/compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent product_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive product_categories[] @relation("recursive")

  @@unique([name])
  @@index([parent_id])
}

/// Product option entity - Implements products' option normalization requirement.
///
/// Represents a single specifiable option (e.g., color, size) for use in variants. Maintains full 3NF by keeping every atomic choice as a separate record, variants reference these options. For example: 'Color: Red', 'Size: 10'.
///
/// Key relationships: many-to-many with product_variants via join table, belongs to a product.
/// Special behaviors: Option values are language-agnostic and referenced. No calculated in-option fields.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model product_options {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique product option identifier.
  id String @id @db.Uuid

  /// Owns product's {@link products.id} - Each option is scoped to a single product.
  product_id String @db.Uuid

  /// Type of option (e.g., 'color', 'size'). Atomic descriptor, no list aggregation.
  option_type String

  /// Atomic option value (e.g., 'Red', 'XL'). Single value per record; reference only.
  value String

  //----
  // RELATIONS
  //----
  product products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  @@index([product_id])
  @@index([option_type(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product tag entity - This implements the tagging requirement, supporting extensible and AI-generated tags for search/discovery.
///
/// Represents a single logical tag, maintained fully normalized (one tag per record). Used for many-to-many linking to products via a junction; enables advanced AI/ML. E.g., 'Eco-friendly', 'AI-generated: trending', '2025 Spring'.
///
/// Key relationships: many-to-many with products via join table. Not bound to product for de-dupe.
/// Special behaviors: Cannot be deleted if mapped to product by business rule (handled in logic, not schema).
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model product_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique tag identifier.
  id String @id @db.Uuid

  /// Atomic tag value: presented for searches, filtering, and AI workflows. Not compound fields. E.g., 'Seasonal'.
  value String

  /// Timestamp for tag creation; enables audit, compliance, and ML features.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([value])
}

/// Product media entity - Implements digital asset management for products, normalization requirement for file/asset reference.
///
/// Represents a single atomic asset—image, video, PDF—linked to a product or variant. Asset metadata and localization handled at field level. Maintains normalization by not duplicating media data. E.g., 'main.jpg', 'unboxing.mp4'.
///
/// Key relationships: linked to product or product_variant, not both. Media may be globally reused via indirect links.
/// Special behaviors: File content is reference only (URI), not stored in DB.
///
/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model product_media {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique asset identifier.
  id String @id @db.Uuid

  /// Linked product's {@link products.id}. Exactly one of product_id or product_variant_id must be non-null.
  product_id String? @db.Uuid

  /// Linked product variant's {@link product_variants.id}. Enforces exclusivity, one of two FK must be set.
  product_variant_id String? @db.Uuid

  /// Atomic URI to remote asset (never stores blobs in DB).
  uri String @db.VarChar(80000)

  /// Type of asset ('image', 'video', etc).
  media_type String

  /// Locale/region of this asset, per i18n/a11y. E.g.: 'ko-KR'.
  locale String

  /// Accessibility alt text for asset, complying with a11y WCA2.
  alt_text String

  /// Asset creation timestamp; audit/evidence field, 3NF.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product products? @relation(fields: [product_id], references: [id], onDelete: Cascade)
  variant product_variants? @relation(fields: [product_variant_id], references: [id], onDelete: Cascade)

  @@index([product_id])
  @@index([product_variant_id])
  @@index([alt_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Inventory entity - Implements core inventory tracking and evidence preservation requirement.
///
/// Represents a normalized, atomic inventory record for product variants. No aggregate or pre-computed stock. Maintains 3NF by keeping each update/event in a separate record (history by design). For example: inventory for 'Nike Air Max 2025, Size 10'.
///
/// Key relationships: One-to-one links with product_variant; ties to evidence/events for audit. 
