  description String

  /// Evidence creation timestamp; 3NF compliance, chronological audit.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  catalog_event catalog_events? @relation(fields: [catalog_event_id], references: [id], onDelete: Cascade)

  @@index([catalog_event_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-cart_order.prisma:
/// [Cart management] - This implements the requirement for intelligent, audit-preserving cart management from the 'Intelligent Cart and Order Processing Requirements Specification'.
///
/// This model represents a user's persistent cart, maintaining strict data integrity, full auditability, session support, and secure linkage to user or session. It ensures 3NF normalization by keeping only atomic and essential cart-level data; item-level details reside in cart_item. Example: recovering a user's cart across multiple devices or after authentication.
///
/// Key relationships: references user, session, and cart_item models for ownership, context, and item containment.
/// Special behaviors: Cart identity is unique; maintains only normalized relations, all item data tracked via junction table.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model cart {
  //----
  // COLUMNS
  //----
  /// Primary Key. Identifies each cart instance uniquely.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}
  /// The primary account associated with this cart; enables cart persistence across devices and sessions.
  user_id String @db.Uuid

  /// Associated session's {@link sessions.id}
  /// Optional. Associates anonymous/pre-login carts; provides seamless upgrade upon login.
  session_id String? @db.Uuid

  /// [Cart creation timestamp] - Implements evidence and regulatory requirements. Used for audit logging, recovery, and analytics. Ensures normalization by tracking atomic event only. Ex: '2025-06-10T04:59:24' when cart first initiated.
  created_at DateTime @db.Timestamptz

  /// [Cart update timestamp] - Implements traceability and audit requirements, storing only atomic last-changed value. Allows tracking of recent activity. Ex: '2025-06-10T05:03:45' after a product added.
  updated_at DateTime @db.Timestamptz

  /// [Soft deletion timestamp] - Implements compliance, right-to-be-forgotten, and data integrity requirements. Null if active, set on removal for evidence trail. Ex: null for active, timestamp for deleted cart.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user    users     @relation(fields: [user_id], references: [id], onDelete: Cascade)
  session sessions? @relation(fields: [session_id], references: [id], onDelete: Cascade)

  cart_item cart_item[]
  order     order[]

  @@index([session_id])
  @@index([user_id, created_at])
}

/// [Cart item detail] - This implements the requirement for normalized, auditable cart item management from the 'Intelligent Cart and Order Processing Requirements Specification'.
///
/// Represents each item in a user's cart, maintaining full normalization (3NF). Item quantities, variant choice, and intent are recorded atomically. Auditability is ensured by timestamping and separate evidence models where required. Example: when a user adds three units of a size-M, green T-shirt variant to cart.
///
/// Key relationships: references cart, product_variant for linkage; product reference maintained via product_variant only. No calculated data; all denormalization only in views.
/// Special behaviors: One cart_item per variant per cart; unique constraint enforced.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model cart_item {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies this cart-item record.
  id String @id @db.Uuid

  /// Parent cart's {@link cart.id}
  /// Links this item to the cart that holds it.
  cart_id String @db.Uuid

  /// Product variant's {@link product_variants.id}
  /// Links to the specific SKU/configuration the user intends to buy.
  product_variant_id String @db.Uuid

  /// [Quantity desired] - Implements cart quantity requirements. Stores atomic, user-specified intent. Ex: '3' for three items of the variant.
  quantity Int @db.Integer

  /// [Item addition timestamp] - Serves evidence and analytics needs. Timestamp for when specific item added to cart. Ex: '2025-06-10T04:59:24'.
  added_at DateTime @db.Timestamptz

  /// [Last update timestamp] - Tracks modification; e.g. quantity update. Normalized (not derived) atomic history. Ex: '2025-06-10T05:00:00'.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  cart            cart             @relation(fields: [cart_id], references: [id], onDelete: Cascade)
  product_variant product_variants @relation(fields: [product_variant_id], references: [id], onDelete: Cascade)

  @@unique([cart_id, product_variant_id])
  @@index([product_variant_id])
  @@index([cart_id, added_at])
}

/// [Order lifecycle record] - Implements the requirement for normalized, robust, evidence-preserving order process management from the requirements specification.
///
/// Each order record represents a unique commerce transaction, including linkage to user, cart, payment, and state tracking. Strict 3NF assures no duplication—order_items contain line-level details. All status/history/evidence handled via related tables. Example: new purchase by user, tracked through all subsequent states (placed, shipped, completed).
///
/// Key relationships: references user, cart, payment and state-tracking models for full join capability.
/// Special behaviors: Atomic values only (total, status, etc. never pre-calculated). Order evidence and logs stored externally for compliance.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model order {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID per order transaction.
  id String @id @db.Uuid

  /// Ordering user's {@link users.id}
  /// Links order to user account for audit and analytics.
  user_id String @db.Uuid

  /// Source cart's {@link cart.id}
  /// Links to the cart used to place this order. Enables full evidence chain for compliance.
  cart_id String @db.Uuid

  /// [Order creation timestamp] - Required by audit, compliance, and analytics. Atomic, strictly non-duplicated event. E.g., '2025-06-10T04:59:24'.
  created_at DateTime @db.Timestamptz

  /// [Order update timestamp] - Captures atomic change events for evidence and operational review. E.g., '2025-06-10T05:30:00'.
  updated_at DateTime @db.Timestamptz

  /// [Soft delete marker] - For compliance and historic evidence, set if order is voided/cancelled; otherwise null. Never physically deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)
  cart cart  @relation(fields: [cart_id], references: [id], onDelete: Cascade)

  order_item     order_item[]
  order_status   order_status[]
  order_log      order_log[]
  order_evidence order_evidence[]
  discounts      discounts[]
  transactions   transactions[]
  refunds        refunds[]

  @@index([cart_id])
  @@index([user_id, created_at])
}

/// [Order line-level detail] - Implements the requirement for strictly normalized, traceable order item management.
///
/// Represents each SKU/configuration in an order, recording atomic quantity and reference to product_variant. Ensures full 3NF by detaching all calculations, price, or analytic rollup. All audit trails and evidence for each action reside in related tables. Example: order includes 2 blue jeans, variant #7.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model order_item {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for line item.
  id String @id @db.Uuid

  /// Parent order's {@link order.id}
  /// Links to the order containing this line item.
  order_id String @db.Uuid

  /// Product variant's {@link product_variants.id}
  /// Spell out the line as describing which exact stock-keeping unit.
  product_variant_id String @db.Uuid

  /// [Ordered quantity] - Stores user-purchased units. Ensures atomic, normalized order content. E.g., user orders 2 of variant #7.
  quantity Int @db.Integer

  /// [Addition to order timestamp] - For evidence and tracking requirements. Details time when item became part of order. E.g., '2025-06-10T04:59:24'.
  added_at DateTime @db.Timestamptz

  /// [Update timestamp] - For last atomic update to line item details. For event logging. E.g., '2025-06-10T05:04:03'.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order           order            @relation(fields: [order_id], references: [id], onDelete: Cascade)
  product_variant product_variants @relation(fields: [product_variant_id], references: [id], onDelete: Cascade)

  @@unique([order_id, product_variant_id])
  @@index([product_variant_id])
  @@index([order_id, added_at])
}

/// [Order status tracking] - Implements normalized, evidence-enabled order lifecycle state management as required for audit, analytics, and compliance.
///
/// Each record logs a status transition for an order, rather than storing 'latest' status inline. Full history of order state is tracked as a sequence by timestamps. Example: 'pending', 'paid', 'shipped', 'delivered'.
///
/// Key relationships: references order for parent linkage.
/// Special behaviors: No denormalization; only atomic status per row. Materialized views to hold summary/latest states.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model order_status {
  //----
  // COLUMNS
  //----
  /// Primary Key. One per status change event.
  id String @id @db.Uuid

  /// Target order's {@link order.id}
  /// Defines which order this status record is about.
  order_id String @db.Uuid

  /// [Order status code] - Represents atomic order state (e.g., 'pending', 'paid', 'shipped'). Compliance: values are strictly controlled by system logic or enumeration.
  status_code String

  /// [Status change timestamp] - Implements complete event history. Atomic per change. E.g., '2025-06-10T05:12:09'.
  changed_at DateTime @db.Timestamptz

  /// [Status changer] - For evidence and audit, identifies the user or system actor triggering the state change. Links to user.id or reserved system id. Null if system-automated.
  changed_by String? @db.Uuid

  //----
  // RELATIONS
  //----
  order order @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@index([order_id, changed_at])
}

/// [Order event logging] - Implements the requirement for immutable, tamper-evident record of all material order-related actions.
///
/// Each record logs an event (e.g., creation, update, state transition, evidence attachment) for an order, including timestamps and relevant actor info. All analytics, AI-driven detection, and compliance evidence are sourced from this log. Full 3NF compliance is achieved—no calculated or summary fields.
///
/// Key relationships: references target order; may reference evidence where applicable.
/// Special behaviors: Immutable logs; complete itemization (no aggregations within table).
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model order_log {
  //----
  // COLUMNS
  //----
  /// Primary Key for log entry.
  id String @id @db.Uuid

  /// Target order's {@link order.id}
  /// Order event relates to this specific transaction.
  order_id String @db.Uuid

  /// Linked evidence's {@link order_evidence.id}
  /// Optional; logs external file or digital signature as audit evidence for this event.
  evidence_id String? @db.Uuid

  /// [Event type] - Type or category of event; e.g., 'create', 'update', 'status_change', 'attach_evidence'. Normalized, not pre-calculated. Used for filtering, audit, analytics.
  event_type String

  /// [Event detail] - Atomic description, not derived or aggregated. E.g., 'Order was shipped via courier'.
  event_description String

  /// [Event timestamp] - Exact time when event occurred; essential for evidence compliance and analytics.
  event_time DateTime @db.Timestamptz

  /// [Event actor] - User ID or system actor responsible for event. Used in compliance analysis. Null if unauthenticated or system auto-action.
  actor_id String? @db.Uuid

  //----
  // RELATIONS
  //----
  order    order           @relation(fields: [order_id], references: [id], onDelete: Cascade)
  evidence order_evidence? @relation(fields: [evidence_id], references: [id], onDelete: Cascade)

  @@index([evidence_id])
  @@index([order_id, event_time])
}

/// [Order evidence registry] - Satisfies requirement to record all compliance, audit or dispute evidence associated with order operations.
///
/// Holds atomic pointers to files, digital receipts, or cryptographic proof objects related to a specific order. Evidence records are separate for full normalization. Example: PDF invoice, delivery photo, digital signature pertaining to an order.
///
/// Key relationships: links order and potentially the user or system actor providing the evidence.
/// Special behaviors: Only atomic and external reference fields allowed; all denormalization in materialized view.
///
/// @namespace CartOrder
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model order_evidence {
  //----
  // COLUMNS
  //----
  /// Primary Key for evidence record.
  id String @id @db.Uuid

  /// Associated order's {@link order.id}
  /// Defines which order this evidence relates to.
  order_id String @db.Uuid

  /// [Evidence type] - Type of evidence (e.g., 'invoice', 'signature', 'photo', 'receipt'). Normalized, strictly conformance for evidence audit. E.g., 'invoice'.
  evidence_type String

  /// [Evidence URI] - URI/location to external asset or file. Atomic, not aggregated. E.g., 'https://evidence.bucket/signed-invoice.pdf'.
  evidence_uri String @db.VarChar(80000)

  /// [Provided timestamp] - When the evidence was recorded into the system. Serves compliance and analytics. E.g., '2025-06-10T06:09:00'.
  provided_at DateTime @db.Timestamptz

  /// [Provider/actor reference] - User or third-party id responsible for provision. For traceability, audit and compliance. Null if system-automated.
  provided_by String? @db.Uuid

  //----
  // RELATIONS
  //----
  order order @relation(fields: [order_id], references: [id], onDelete: Cascade)

  order_log order_log[]

  @@index([order_id, provided_at])
}

schemas.schema-04-payment_discount.prisma:
/// [Payment Record] - This implements the recording of all monetary operations from the requirements analysis, specifically the 'secure, traceable, and compliant payment operations' and 'transaction integrity' points under AI-Driven Discount & Payment Systems. 
///
/// Maintains 3NF by separating atomic payment data from aggregated/AI-inferred outcomes. For example, each payment event (checkout, refund, wallet top-up) is represented as a unique entry, providing a clear evidence trail.
///
/// Key relationships: payment_methods for source, transactions as the business event driver, user linkage for payer/payee integrity. 
/// Special behaviors: immutable record post-creation (all changes are audited by payment_audit), PCI compliance enforced by business logic.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model payments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each payment record.
  id String @id @db.Uuid

  /// Linked transaction's {@link transactions.id}. Connects the payment to its parent business event for traceability and reconciliation.
  transaction_id String @db.Uuid

  /// Payment method's {@link payment_methods.id}. Specifies the method used for this payment (credit card, wallet, etc).
  payment_method_id String @db.Uuid

  /// [Monetary amount] - Implements the requirement for accurate financial ledger. The value of this payment, always positive. Maintains atomicity for compliance and analytics. For example, a purchase worth $99.99 or partial refund of $10.00.
  amount Float @db.DoublePrecision

  /// [Currency code] - Implements multi-currency/locale requirement. 3-letter ISO code, e.g., USD, KRW, EUR. Normalized to prevent code confusion. Used for all reporting and conversions.
  currency String

  /// [Payment status] - Implements lifecycle & auditability requirement. Values: pending, completed, failed, refunded, held, etc. Atomic by being tracked per payment; end-to-end state traces go to payment_audit table.
  status String

  /// [Initiation timestamp] - Implements evidence preservation and audit trail. The moment this payment operation (attempt) was started. Always set at record creation. Used for forensic traceability.
  initiated_at DateTime @db.Timestamptz

  /// [Completion timestamp] - For state transition/tracking requirement. The moment the payment succeeded/failed. Nullable when pending. Used in compliance/reconciliation.
  completed_at DateTime? @db.Timestamptz

  /// [Optional payment description] - Business-facing note or payment memo. Implements requirement for evidence context/supporting documentation; not mandatory for atomicity.
  description String?

  //----
  // RELATIONS
  //----
  transaction    transactions    @relation(fields: [transaction_id], references: [id], onDelete: Cascade)
  payment_method payment_methods @relation(fields: [payment_method_id], references: [id], onDelete: Cascade)

  refunds refunds[]

  @@index([transaction_id, initiated_at])
  @@index([payment_method_id, initiated_at])
}

/// [Payment Method Catalog] - Implements the requirement for modular payment method extensibility in the Payment System Architecture section. Manages all user-supported and 3rd-party payment instruments.
///
/// Maintains 3NF by storing atomic payment instrument data for each logical method (e.g., credit card, wallet, crypto account), avoiding redundancy and storing no aggregated fields. For example, a user might have multiple cards and wallets associated here.
///
/// Key relationships: Used by payments, referenced by vouchers or campaigns. Special behaviors: supports inactivation rather than deletion for evidence preservation and ongoing compliance.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model payment_methods {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the payment method.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Which user owns or registers this payment method.
  user_id String @db.Uuid

  /// [Payment method type] - Required for payment routing and compliance logic. E.g., VISA, Mastercard, PayPal, Internal Wallet, Crypto. Normalized to keep atomic per-method information. For example, prevents inconsistent labels.
  type String

  /// [Masked display field] - Implements PCI compliance and business UI logic for safe display. Stores last N digits or partial ID, never sensitive data. Maintains atomicity. For example, 4242 for a VISA card, 0xAb... for wallet.
  masked_detail String

  /// [Provider/source platform] - For extensible payment rails and auditability. Not always present (e.g., direct bank transfer). Records vendor for reconciliation. Example: Toss, Stripe, Binance.
  provider String?

  /// [Activation flag] - Maintains audit/evidence requirements for never deleting payment methods. Only inactive if revoked/expired/deregistered. Required for evidence compliance.
  active Boolean

  /// [Creation timestamp] - For audit trail and evidence preservation. Set on method entry record creation. Used in reporting and compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  payments payments[]
  vouchers vouchers[]

  @@unique([user_id, masked_detail])
  @@index([type, active])
}

/// [Discount Record] - Implements logical representation of all discounts applied within the system, as required for 'auditable, traceable, and AI-driven discounting' in the requirements. Records only atomic logic, with all calculations performed at runtime or in materialized views.
///
/// Maintains 3NF by separating discount logic/ref into discount_rules. Applied discounts per order or item reference this table, never storing totalled values except via linkage.
///
/// Key relationships: discount_rules, orders; special behaviors: immutable after application, with all changes logged via payment_audit.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discounts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique discount operation.
  id String @id @db.Uuid

  /// Linked rule's {@link discount_rules.id}. The rule which provides the logic for this discount entry.
  discount_rule_id String @db.Uuid

  /// Target order's {@link order.id}. The order benefiting from this discount.
  order_id String @db.Uuid

  /// [Discount value] - Implements the requirement for capturing exact benefit conferred, with atomic record of the numerical value (always negative or 0). Maintains normalization and enables reconciliation/audit. For example, -5.00 for a $5 discount.
  amount Float @db.DoublePrecision

  /// [Time of application] - Required for audit/evidence, records when the discount was actually attached to the order.
  applied_at DateTime @db.Timestamptz

  /// [Discount notes/context] - Implements requirement for transparency and traceability, e.g. which campaign, customer, or business rule applied. Atomic, optional.
  notes String?

  //----
  // RELATIONS
  //----
  discount_rule discount_rules @relation(fields: [discount_rule_id], references: [id], onDelete: Cascade)
  order         order          @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@index([order_id])
  @@index([discount_rule_id, applied_at])
}

/// [Discount Rule Registry] - Implements modular management of discount logic for the Discount & Payment Core. Records normalized, AI/model-driven or administrator-created discount strategies, never the calculated results. Fulfills the requirement to maintain audit-ready, explainable, and reusable discount rule definitions.
///
/// 3NF maintained by isolating parameters, such as type, amount, configuration, and referencing origin (e.g., campaign, voucher).
///
/// Key relationships: discount_campaigns as creators/assigners. Used by discounts. Special: deactivation for audit purposes; can reference AI model versions if used for A/B or ML-discounting.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discount_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the discount rule.
  id String @id @db.Uuid

  /// Discount campaign's {@link discount_campaigns.id}. The campaign associated with this rule for aggregation and analytics.
  campaign_id String? @db.Uuid

  /// [Rule type] - Required for runtime discounting. Configurable value (e.g., 'percentage', 'fixed', 'bogo', 'ml-model', etc). Enforces rule-driven modularity. Example: 'percentage' or 'dynamic-ai'.
  type String

  /// [Rule value] - Stores the core numeric for the discount computation (e.g., 20.0 for a 20% rule, 10.00 for $10 fixed). Maintains 3NF.
  value Float @db.DoublePrecision

  /// [Activation flag] - If false, this rule is archived/disabled but included for evidence. Implements requirement for rule lifecycles and traceable config change.
  active Boolean

  /// [Creation timestamp] - Maintains audit and compliance. For example, date when administrator or AI model created this rule.
  created_at DateTime @db.Timestamptz

  /// [AI Model Version] - Links to {@link ai_model_versions.id} if this rule is generated or managed by a specific AI/ML model version (for explainability, audit).
  ai_model_version_id String? @db.Uuid

  //----
  // RELATIONS
  //----
  campaign discount_campaigns? @relation(fields: [campaign_id], references: [id], onDelete: Cascade)

  discounts discounts[]

  @@index([campaign_id, active])
}

/// [Discount Campaign Definition] - Implements requirements for campaign lifecycle, auditability, modular campaign-based discounting. Design allows grouping/analytics over a series of discounts and their rules.
///
/// Maintains full normalization by separating campaign attributes (name, time, status) from rule application.
///
/// Key relationships: discount_rules (rules), referenced from discounts/carts/orders. Special: can be deactivated but never deleted, and includes event evidence for traceability.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discount_campaigns {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique discount campaign.
  id String @id @db.Uuid

  /// [Campaign name] - Req. for grouping and operator reporting (e.g. Black Friday 2025). Atomic and normalized.
  name String

  /// [Campaign description] - Optional context and business notes (e.g. rules, partners). Maintains auditability.
  description String?

  /// [Start time] - Implements evidence/traceability. When this campaign becomes active for discount rule matching. Maintains normalization.
  start_at DateTime @db.Timestamptz

  /// [End time] - Campaign end date for reporting and eligibility. Used in audits and regulatory logs. Nullable for open campaigns.
  end_at DateTime? @db.Timestamptz

  /// [Campaign active flag] - If false, campaign is archived and no longer matchable. Maintains evidence, 3NF, and compliance.
  active Boolean

  /// [Campaign creation timestamp] - Required for audit trail, reporting, and evidence. Set at insertion, not updated.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discount_rules discount_rules[]
  vouchers       vouchers[]
  loyalty_points loyalty_points[]

  @@unique([name, start_at])
}

/// [Transaction Master Record] - Fulfills the requirement that every business event causing a payment has a single, evidence-preserving, auditable record. Maintains 3NF by holding one row per transaction event (e.g. an order checkout, a wallet top-up) and separating linked payments, refunds, and discounts into their own tables.
///
/// Key relationships: Reference to orders, user. Special behaviors: immutable once recorded except notes (audited by payment_audit table), all monetary activity references a transaction id.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model transactions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Represents the unique identifier for each transaction event.
  id String @id @db.Uuid

  /// Transaction initiator's {@link users.id}. Links actions to specific identity for audit, fraud prevention, and analytics.
  user_id String @db.Uuid

  /// Linked order's {@link order.id}. Which order or business event this transaction is for (or null for wallet loads, standalone events).
  order_id String? @db.Uuid

  /// [Transaction type] - Required, fulfills compliance for event classification (e.g. purchase, refund, credit, debit, wallet-topup). Enforces analytics/audit requirements.
  type String

  /// [Event time] - Start time of the business event, fulfills evidence requirements and enables chronological reconstruction.
  created_at DateTime @db.Timestamptz

  /// [Business event memo/description] - Optional context for reporting, audit, or customer support.
  description String?

  //----
  // RELATIONS
  //----
  user  users  @relation(fields: [user_id], references: [id], onDelete: Cascade)
  order order? @relation(fields: [order_id], references: [id], onDelete: Cascade)

  payments       payments[]
  loyalty_points loyalty_points[]
  refunds        refunds[]

  @@index([order_id])
  @@index([user_id, created_at])
}

/// [Voucher/Loyalty Asset] - Implements the requirement for voucher, gift card, or pre-purchased credit support. Each is tracked as an independent asset, enabling compliance with prepaid, gift, refund, or promotional voucher flows.
///
/// Maintains atomic record per voucher, with lifecycle tracking for issuance, redemption, audit trail on all changes. Never deleted for evidence.
///
/// Key relationships: users (owner), payment_methods (if method-specific/voucher activation/restriction applies), campaign (for analytics/tracking), orders (redemption). Special: evidence chain for regulatory compliance.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model vouchers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique voucher asset.
  id String @id @db.Uuid

  /// Voucher owner's {@link users.id}. For gift/asset transfer or loyalty programs.
  user_id String @db.Uuid

  /// Issuing campaign's {@link discount_campaigns.id}. For business tracking and analytics integration.
  campaign_id String? @db.Uuid

  /// Payment method constraint's {@link payment_methods.id} (optional). Restricts redemption to method (e.g. in-app, crypto, external card).
  payment_method_id String? @db.Uuid

  /// [Voucher code] - Unique, human-readable alphanumeric. Implements redemption security and audit; not a calculated field. For example: GIFT-2024-JANE-XYZ.
  code String

  /// [Current amount] - The exact value (at issue or updated on use) remaining on this voucher. Edited only through auditable operations. Maintains 3NF. Example: 50.00 for $50 voucher.
  balance Float @db.DoublePrecision

  /// [Voucher currency] - 3-letter ISO code; enforces multicurrency design and compliance. E.g., USD, EUR.
  currency String

  /// [Expiration date] - Timestamp when voucher becomes invalid. Nullable for non-expiring. Satisfies compliance for customer comms and refunds.
  expires_at DateTime? @db.Timestamptz

  /// [Asset issue timestamp] - When voucher assigned or loaded. Enforced as immutable. Maintains audit.
  created_at DateTime @db.Timestamptz

  /// [Redemption/usage timestamp] - If voucher is single-use or depleted. Nullable for as-yet-unredeemed codes. Maintains normalization.
  redeemed_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user           users               @relation(fields: [user_id], references: [id], onDelete: Cascade)
  campaign       discount_campaigns? @relation(fields: [campaign_id], references: [id], onDelete: Cascade)
  payment_method payment_methods?    @relation(fields: [payment_method_id], references: [id], onDelete: Cascade)

  @@unique([code])
  @@index([user_id])
  @@index([campaign_id])
  @@index([payment_method_id])
}

/// [Loyalty Points Ledger] - Implements loyalty programs per requirements, ensuring all point accruals/deductions are atomic, traceable, and normalized. Directly supports point-of-sale, campaign, and retroactive benefit application via reference to user/event/campaign.
///
/// Maintains one record per transaction/event (3NF), while summaries and analytics are computed in materialized views only.
///
/// Key relationships: users (owner), transactions (origin event), campaigns (linked context), referenced in rewards, discounts.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model loyalty_points {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique loyalty points ledger entry.
  id String @id @db.Uuid

  /// Points holder's {@link users.id}. Matches accrual/deduction to the beneficiary of points.
  user_id String @db.Uuid

  /// Origin transaction's {@link transactions.id}. Details which business event granted/used points.
  transaction_id String? @db.Uuid

  /// Linked campaign's {@link discount_campaigns.id}, if any, for analytics. Nullable when directly earned (e.g. referral, review).
  campaign_id String? @db.Uuid

  /// [Points value] - Exact points earned/spent in this event. Always positive or negative, never calculated field. Example: 10.0 earned on purchase, -5.0 for redemption.
  points Float @db.DoublePrecision

  /// [Points event type] - Required for analytics and business reporting. E.g., 'earn', 'redeem', 'bonus', 'expire'. Atomic and normalized.
  type String

  /// [Ledger event timestamp] - Required for evidence and compliance; tracks the atomic moment of this points event.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user        users               @relation(fields: [user_id], references: [id], onDelete: Cascade)
  transaction transactions?       @relation(fields: [transaction_id], references: [id], onDelete: Cascade)
  campaign    discount_campaigns? @relation(fields: [campaign_id], references: [id], onDelete: Cascade)

  @@index([transaction_id])
  @@index([campaign_id])
  @@index([user_id, created_at])
}

/// [Refund Record] - Fulfills traceable, auditable refund flows for partial or full payments, applying to the PCI-regulated payment and order flows. Normalized to one row per refund event, with order, payment, and transaction references as applicable.
///
/// All refund calculations/aggregates are to be computed in views. 3NF maintained by only storing atomic per-operation data.
///
/// Key relationships: payments (source), transactions (business event), orders (context). Special: always documented in payment_audit for compliance and evidence.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique refund event.
  id String @id @db.Uuid

  /// Refunds original payment's {@link payments.id}. Traceable, required for audit and compliance.
  payment_id String @db.Uuid

  /// Business event's {@link transactions.id}. The transaction driving this refund (for evidence chain and aggregation).
  transaction_id String @db.Uuid

  /// Relevant order's {@link order.id}. Context for reporting, analytics, and recovery; nullable for standalone refunds. Fulfills regulatory traceability.
  order_id String? @db.Uuid

  /// [Refund amount] - Atomic per-refund event (no aggregate). Value refunded in currency. Maintains audit and evidence, supports negative for chargebacks.
  amount Float @db.DoublePrecision

  /// [Currency code] - Enforces multi-currency design; matches payment/order context. 3-letter ISO code.
  currency String

  /// [Refund status] - Completes state machine for audit/compliance (e.g., requested, processed, rejected, completed). Always atomic; tracked for evidence.
  status String

  /// [Request timestamp] - When refund request was filed. Atomic for evidence chain and customer service trace. Set at creation.
  requested_at DateTime @db.Timestamptz

  /// [Completion timestamp] - When refund finalized. Nullable for pending/cancelled. Maintains compliance and user transparency.
  completed_at DateTime? @db.Timestamptz

  /// [Refund reason/notes] - For regulatory/contextual info. Documents why a refund is issued; atomic per event.
  reason String?

  //----
  // RELATIONS
  //----
  payment     payments     @relation(fields: [payment_id], references: [id], onDelete: Cascade)
  transaction transactions @relation(fields: [transaction_id], references: [id], onDelete: Cascade)
  order       order?       @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@index([order_id])
  @@index([payment_id, requested_at])
  @@index([transaction_id, requested_at])
}

/// [Payment/Discount/Transaction Audit Log] - Implements evidence chain, immutability, and compliance requirements from multiple specification points. This table tracks all changes (state, value, configuration) in payments, discounts, refunds, voucher activities, etc. No aggregated or calculated values are persisted; all logs are atomic, normalized events.
///
/// Each log entry references the affected entity (by type), time of event, actor (user/system). Provides audit, forensic, fraud mitigation and compliance trail.
///
/// @namespace PaymentsDiscounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model payment_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit log entry.
  id String @id @db.Uuid

  /// Actor's {@link users.id}. Who performed this audit-tracked action; user or system account. Null for automated events but trackable for regulatory trace.
  user_id String? @db.Uuid

  /// [Entity type] - Implements polymorphic audit of payments, discounts, refunds, etc. Required for evidence/data tracking. For example: 'payment', 'discount', 'refund'.
  entity_type String

  /// [Entity ID] - Target entity's primary key. Maintains atomicity. For example: references payments.id or discounts.id.
  entity_id String @db.Uuid

  /// [Action taken] - Logical action (e.g., 'create', 'update', 'apply', 'fail', 'refund') accomplished by this audit event. Required for end-to-end evidence chain. Maintains normalization.
  action String

  /// [Previous state/value] - Optional snapshot for evidence. For example, payment status before update. Nullable for creates. Maintains normalization and evidence context.
  old_value String?

  /// [New state/value] - Resulting value or config. Nullable for deletes.
  new_value String?

  /// [Audit event time] - Atomic/durable record of the precise event occurrence. Maintains 3NF, audit, and compliance requirements.
  timestamp DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users? @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([entity_type, entity_id, timestamp])
}

schemas.schema-05-communication_review.prisma:
/// [Message Thread] - This implements the conversation thread grouping requirement from the 'Communication, Review & Sentiment Analysis' module. 
///
/// Groups together all related user-to-user or user-to-support messages into distinct threads, enabling clear organization and session-based conversation flows. Maintains 3NF by never storing derived or redundant message data—each thread keeps only identifying and stateful information. For example, a single thread can encompass multiple back-and-forth messages between a customer and support agent.
///
/// Key relationships: links to participants via foreign keys or through junction tables (future extension), referenced by messages and possibly notifications.
/// Special behaviors: Thread archival/deletion must preserve audit trails; never hard-delete for compliance.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model message_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Creator user's {@link users.id}.
  created_by_user_id String @db.Uuid

  /// [Thread subject] - Implements the requirement for thread labeling and discoverability.
  ///
  /// Business meaning: Subject or title for top-level navigation, search, and summarization. Ensures normalization by separating core thread data from actual messages. Example: 'Order #1342 Support'.
  subject String

  /// [Thread archival flag] - Implements requirement for evidence tracking and data preservation. Business meaning: Soft deletion/archival for audit purposes. Normalization: separate status flag, not affecting contained messages. Example: Thread archive action by user or admin.
  archived Boolean

  /// [Thread creation timestamp] - Implements audit/evidence requirement. Timestamp when thread was created. Normalization: atomic time, never duplicated from contained messages. Example: Show creation moment in thread list, regardless of message activity.
  created_at DateTime @db.Timestamptz

  /// [Thread last modified timestamp] - Implements recency for sorting/searching. Updated when participants act on the thread (send/receive message, archive, etc.). Normalization: always atomic, never copied or calculated from child message times. Example: Sort by latest update in UI.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  created_by_user users @relation(fields: [created_by_user_id], references: [id], onDelete: Cascade)

  messages      messages[]
  notifications notifications[]

  @@index([created_by_user_id, created_at])
}

/// [Message] - Implements the transactional communication entity requirement from the 'Communication, Review, and Sentiment Analysis' document. 
///
/// Represents individual messages (text, image, or system notification) exchanged within a message thread. Maintains strict 3NF—only atomic message and linkage data. For example, a customer question and a vendor response, with each message linked to user and thread.
///
/// Key relationships: references sender (user), target thread, and optionally parent message (for replies/quoting). 
/// Special behaviors: All changes are audited; messages are never deleted, only flagged. Attachments/media handled externally for evidence integrity.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model messages {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Thread's {@link message_threads.id} this message belongs to.
  thread_id String @db.Uuid

  /// Sender's {@link users.id}.
  sender_user_id String @db.Uuid

  /// Optional parent message's {@link messages.id} for reply/tree structure.
  parent_message_id String? @db.Uuid

  /// [Message content] - Implements the raw message body/evidence tracking. Primary user/customer or system content. Never pre-calculated. Example: Support question, reply, or notification message.
  content String

  /// [Message type] - Implements conversational workflow logic. Values include: 'user', 'system', 'notification', or custom types. Maintains normalization by storing type info atomically. Example: 'user' = human, 'system' = order status update, etc.
  message_type String

  /// [Send timestamp] - Time the message was dispatched. Maintains normalization by being atomic, always set on creation. Example: Populate message log or sort.
  sent_at DateTime @db.Timestamptz

  /// [Read timestamp] - Time the recipient viewed the message. Maintains normalization by being optional, never duplicated or inferred. Example: Unread badge logic.
  read_at DateTime? @db.Timestamptz

  /// [Archived flag] - Strict evidence preservation, marking messages without deletion. Normalization compliance: atomic per message, not inherited from thread. Example: Hide from primary inbox but retained for audit.
  archived Boolean

  //----
  // RELATIONS
  //----
  thread         message_threads @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  sender_user    users           @relation(fields: [sender_user_id], references: [id], onDelete: Cascade)
  parent_message messages?       @relation("recursive", fields: [parent_message_id], references: [id], onDelete: Cascade)

  recursive messages[] @relation("recursive")

  @@index([sender_user_id])
  @@index([parent_message_id])
  @@index([thread_id, sent_at])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Notification] - Implements the user notification system requirement as described under communication/event modules. 
///
/// Captures system-/event-driven notifications linked to users and, if relevant, threads or orders. Maintains 3NF by never duplicating event data from source entities; only logs atomic notification facts. Example: 'Order shipped', 'New message', or 'Sale started'.
///
/// Key relationships: references user, may link to thread or other context entity.
/// Special behaviors: Tracks read/unread status and delivery timestamp; old records never deleted for evidence.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Notified user's {@link users.id}.
  user_id String @db.Uuid

  /// Related thread's {@link message_threads.id}, if any.
  thread_id String? @db.Uuid

  /// [Type indicator] - Implements notification categorization; e.g., 'system', 'message', 'promotion'. Normalization: Single source of event type per notification. Example: Used for filtering in notification center.
  notification_type String

  /// [Notification content] - Implements atomic event evidence; real message dispatched to user. Normalization: content held here, not duplicated from other entities. Example: 'Your order #1234 shipped'.
  content String

  /// [Notification dispatch time] - Time when delivered to user. Normalization: atomic per notification. Example: Sorting notifications, TTL enforcement.
  sent_at DateTime @db.Timestamptz

  /// [Notification read time] - When user viewed notification. Normalization: atomic, optional per record. Example: Mark as read upon open.
  read_at DateTime? @db.Timestamptz

  /// [Archived flag] - Keeps notification for historical evidence. Never physically deleted. Example: Mute or archive by user action.
  archived Boolean

  //----
  // RELATIONS
  //----
  user   users            @relation(fields: [user_id], references: [id], onDelete: Cascade)
  thread message_threads? @relation(fields: [thread_id], references: [id], onDelete: Cascade)

  @@index([thread_id])
  @@index([user_id, sent_at])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Review] - Implements product/service review entity from the 'Communication, Review & Sentiment Analysis' business module.
///
/// Represents authentic and versioned user-submitted reviews. Maintains strict 3NF: only atomic review attributes—content, media, metadata, never derived or aggregated. Example: User review for a purchased product, versioned for edit history.
///
/// Key relationships: References user, product/service, ties to moderation and sentiment logs.
/// Special behaviors: Supports multilingual data, evidence archiving, evidence-preserving versioning for edits and compliance.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Author user's {@link users.id}.
  user_id String @db.Uuid

  /// Reviewed product's {@link products.id}.
  product_id String @db.Uuid

  /// Optional parent review's {@link reviews.id}, for reply/hierarchical structure.
  parent_review_id String? @db.Uuid

  /// [Review content] - Main review body, implements the core business requirement for evidence-preserved user feedback. Normalization: only atomic text here. Example: User's product experience.
  content String

  /// [Review language code] - Implements multicultural and accessibility requirement. Holds locale for review. Normalization: only atomic value, never derived. Example: 'en', 'ko', 'fr'.
  language_code String

  /// [Review creation timestamp] - When submitted by user. Example: timeline displays, compliance logs.
  created_at DateTime @db.Timestamptz

  /// [Last modification time] - Latest edit, present on update. Example: show edit history.
  updated_at DateTime @db.Timestamptz

  /// [Purchase verification flag] - Implements fraud prevention and authenticity. Set if review relates to verified purchase. Example: 'True' for eligible buyers only.
  verified_purchase Boolean

  /// [Archived flag] - Soft delete for audit and evidence. Never physically removed. Example: Admin-moderated reviews.
  archived Boolean

  //----
  // RELATIONS
  //----
  user          users    @relation(fields: [user_id], references: [id], onDelete: Cascade)
  product       products @relation(fields: [product_id], references: [id], onDelete: Cascade)
  parent_review reviews? @relation("recursive", fields: [parent_review_id], references: [id], onDelete: Cascade)

  recursive               reviews[]                 @relation("recursive")
  review_media            review_media[]
  review_moderations      review_moderations[]
  review_sentiments       review_sentiments[]
  sentiment_analysis_logs sentiment_analysis_logs[]

  @@index([user_id])
  @@index([parent_review_id])
  @@index([product_id, created_at])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Review Media] - Implements the requirement to allow image/video attachments for reviews while enforcing normalization and evidence archiving.
///
/// References review, media asset, and stores metadata. Only atomic linkage and media attributes; evaluation or calculated fields in other tables only (e.g., media count in views). Example: Multiple images for a product review.
///
/// Key relationships: references review and an external media entity (for expansion). 
/// Special behaviors: Only links and descriptive attributes; media storage handled elsewhere.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model review_media {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked review's {@link reviews.id}.
  review_id String @db.Uuid

  /// [Attachment type] - 'image', 'video', etc. Normalization: atomic classification. Example: Used for gallery, filter.
  media_type String

  /// [Media URI] - Directly links to storage asset. Maintains normalization by not duplicating data. Example: S3/GCS location or CDN path.
  uri String @db.VarChar(80000)

  /// [Alt text] - Accessibility and multicultural support. Describes image/video for a11y. Example: 'User photo of red sneakers'.
  alt_text String?

  /// [Display sequence] - Implements ordered media logic. Maintains normalized integer, not inferred or derived. Example: Order of images as shown in UI.
  sequence Int @db.Integer

  //----
  // RELATIONS
  //----
  review reviews @relation(fields: [review_id], references: [id], onDelete: Cascade)

  @@index([review_id, sequence])
}

/// [Review Moderation] - Implements evidence-preserved moderation actions on reviews as required by compliance, fraud prevention, and audit modules. 
///
/// Stores atomic records of each moderation: action, moderator, decision, timestamp, rationale. Maintains strict normalization (no aggregation, no calculated fields). Example: Admin removes, restores, or flags a review for abusive content.
///
/// Key relationships: references moderated review and moderator user.
/// Special behaviors: All moderation events strictly immutable, producing an audit trail.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model review_moderations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Moderated review's {@link reviews.id}.
  review_id String @db.Uuid

  /// Moderator user's {@link users.id}.
  moderator_user_id String @db.Uuid

  /// [Moderation action] - 'remove', 'restore', 'flag', etc. Required for audit. Example: Used as evidence on compliance review.
  action_type String

  /// [Reason/rationale] - Explanation by moderator. Normalization: only atomic string. Example: Why review was removed/flagged.
  rationale String

  /// [Timestamp] - When moderation occurred. Normalized as atomic point in time. Example: Legal holds.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  review         reviews @relation(fields: [review_id], references: [id], onDelete: Cascade)
  moderator_user users   @relation(fields: [moderator_user_id], references: [id], onDelete: Cascade)

  @@index([moderator_user_id])
  @@index([review_id, created_at])
}

/// [Review Sentiment] - Implements versioned and AI-powered sentiment analysis for reviews as described in Sentiment Analysis requirements.
///
/// Captures analysis model/version, result, and timestamp for every processed review. Maintains strict normalization: no pre-calculated fields. Example: 'Positive/negative/neutral' per review version, tied to model run.
///
/// Key relationships: references review and AI model/version.
/// Special behaviors: Multiple entries allowed for model runs, with timestamped trail for evidence.
///
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model review_sentiments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Analyzed review's {@link reviews.id}.
  review_id String @db.Uuid

  /// AI model version's {@link ai_model_versions.id} used for analysis.
  ai_model_version_id String @db.Uuid

  /// [Sentiment result] - Implements the core outcome (e.g., 'positive', 'negative', 'neutral'). Atomic per analysis, never derived. Example: For dashboard reporting.
  sentiment String

  /// [Sentiment score] - Numeric value indicating polarity/confidence. Maintains normalization as atomic output. Example: Model's confidence in prediction.
  score Float @db.DoublePrecision

  /// [Timestamp] - When sentiment analysis executed.
  analyzed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  review           reviews           @relation(fields: [review_id], references: [id], onDelete: Cascade)
  ai_model_version ai_model_versions @relation(fields: [ai_model_version_id], references: [id], onDelete: Cascade)

  @@index([ai_model_version_id])
  @@index([review_id, analyzed_at])
}

/// [Sentiment Analysis Log] - Implements full evidence and model input/output preservation for every sentiment analysis run, fulfilling the tracking requirements set in advanced AI and compliance modules.
///
/// Stores all model input, output, AI version, and raw evidence for legal hold/audit. Maintains strict 3NF by holding only atomic data elements, never calculated or aggregate. Example: A record per sentiment inference, with trace of data and rationale.
///
/// Key relationships: references review, ai_model_version.
/// Special behaviors: Immutable, long-retained for compliance and model debugging.
///
/// @namespace CommunicationReview
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model sentiment_analysis_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Analyzed review's {@link reviews.id}.
  review_id String @db.Uuid

  /// AI version's {@link ai_model_versions.id} used for sentiment.
  ai_model_version_id String @db.Uuid

  /// [Raw model input] - Stores original text or preprocessed structure input to model. Maintains normalization: atomic capture only. Example: JSON of features or string blob.
  raw_input String

  /// [Raw model output] - Full inference result, possibly JSON. Maintains normalization, not aggregated. Example: Model's output structure as-is for trace/debug.
  output String

  /// [Model version string] - Redundant to FK for compliance readability. Maintains normalization: atomic version string. Example: 'v1.2.2-EN-SENTIMENT'.
  model_version String

  /// [Analysis timestamp] - When analysis was run. Maintains normalization as atomic timestamp. Example: Compliance audit.
  analyzed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  review           reviews           @relation(fields: [review_id], references: [id], onDelete: Cascade)
  ai_model_version ai_model_versions @relation(fields: [ai_model_version_id], references: [id], onDelete: Cascade)

  @@index([ai_model_version_id])
  @@index([review_id, analyzed_at])
}

schemas.schema-06-favorites_personalization.pris:
/// [Favorites Management Table] - This implements the favorite/bookmarking system as specified in section 07 of the requirements report.
///
/// Manages the user's bookmarks and favorite items, supporting evidence-based, auditable user preference tracking. Maintains 3NF by separating only the favorite relationship (user-content), leaving additional data (history, metadata, personalization) in related entities. For example, this table allows users to mark any product as a favorite and organizes the link between user and product for AI/analytics workflows.
///
/// Key relationships: Linked to {@link users.id}, {@link products.id}, with cascaded deletion on user or product removal.
/// Special behaviors: Immutable, evidence-preserving (soft-delete with audit via personalization_audit), composite uniqueness constraint to ensure a user cannot favorite the same product twice.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model favorites {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique favorite record identifier, complying with audit and evidence requirements.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}.
  /// Links the favorite action to the profile, supporting analytics, consent, and privacy compliance.
  user_id String @db.Uuid

  /// Target product's {@link products.id}.
  /// Points to the favorited product, supporting contextual personalization, product analytics, and AI recommendations.
  product_id String @db.Uuid

  /// Timestamp for when the favorite record was created. Implements evidence preservation and auditing as required in the compliance sections. For example, enables reconstructing user preference timelines.
  created_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp to maintain evidence preservation and non-repudiation. Null if active. For example, keeps an audit trail for regulatory requests.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user    users    @relation(fields: [user_id], references: [id], onDelete: Cascade)
  product products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  personalization_audits personalization_audits[]

  @@unique([user_id, product_id])
  @@index([product_id])
  @@index([created_at])
}

/// [Bookmark Table] - Implements user-defined bookmark/organization of products/content, as called for in the Favorites and Personalization requirements.
///
/// Acts as a refinement on the favorite concept, enabling organization and metadata for bookmarks. Maintains normalization (3NF) by linking only user and product, and keeping additional metadata (e.g. category/folder/tag) here, rather than the core favorite link. For example, a user can tag or categorize favorites using bookmarks.
///
/// Key relationships: Linked to {@link users.id} and {@link products.id}; supports bidirectional linkage for advanced queries and analytics.
/// Special behaviors: Composite uniqueness constraint for per-user bookmarks; supports optional custom_folder for personalized organization.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model bookmarks {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique bookmark identifier.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}.
  /// Supports permission checks, analytics, and data retrieval.
  user_id String @db.Uuid

  /// Referenced product's {@link products.id}.
  /// Pinpoints the bookmarked product for analysis and retrieval.
  product_id String @db.Uuid

  /// Optional organizational label or folder for this bookmark. Implements user segmentation for evidence and personalization. For example, user groups bookmarks under "Wish List".
  custom_folder String?

  /// Optional user-defined tag for the bookmark for enhanced organization and analytics. Maintains normalization and is kept atomic. For example: "Winter Sale".
  tag String?

  /// Optional user note attached to the bookmark, evidence for personalization. For example, "Gift idea for Mom."
  note String?

  /// Timestamp for bookmark creation, audit and personalization evidence compliance.
  created_at DateTime @db.Timestamptz

  /// Optional timestamp for soft deletion (audit/evidence preservation requirement).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user    users    @relation(fields: [user_id], references: [id], onDelete: Cascade)
  product products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  personalization_audits personalization_audits[]

  @@unique([user_id, product_id])
  @@index([product_id])
  @@index([created_at])
  @@index([note(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Personalization Event Table] - Implements tracking of all personalization actions/events impacting user experience, specified in section 07 and 08 (AI & Data Operations).
///
/// Captures evidence and metadata for when a user receives, reacts to, or interacts with a personalized recommendation. Maintains 3NF by relegating feature data and detailed analytics logs to other tables. For example, this enables tracing which recommendation was shown, clicked, or dismissed.
///
/// Key relationships: Linked to {@link users.id}, {@link recommendations.id}, {@link products.id}. Supports AI model tracking.
/// Special behaviors: Immutable event log for audit/compliance, supports detailed event-type taxonomy via 'event_type'.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model personalization_events {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique record for a personalization event.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Links event to user profile for analytics and personalization history.
  user_id String @db.Uuid

  /// Belonged recommendation's {@link recommendations.id}. Reference to the suggestion served in this event.
  recommendation_id String @db.Uuid

  /// Target product's {@link products.id}. The product associated with the event, for traceability and feedback learning.
  product_id String @db.Uuid

  /// Type of personalization event (e.g., view, click, save, dismiss). Enables advanced analytics and model explainability. Normalized—categorical and atomic. For example: 'RECOMMENDATION_SERVED'.
  event_type String

  /// AI/ML model version used in generating the recommendation; implements explainability and regulatory compliance requirements.
  model_version String

  /// Optional context information for event (device, locale, etc.). Captures multi-channel/locale evidence as per requirements.
  context String?

  /// Timestamp for when personalization event occurred. Implements evidence and audit traceability.
  timestamp DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user           users           @relation(fields: [user_id], references: [id], onDelete: Cascade)
  recommendation recommendations @relation(fields: [recommendation_id], references: [id], onDelete: Cascade)
  product        products        @relation(fields: [product_id], references: [id], onDelete: Cascade)

  personalization_audits personalization_audits[]

  @@index([user_id])
  @@index([recommendation_id])
  @@index([product_id])
  @@index([timestamp])
  @@index([event_type(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([context(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Recommendation Table] - Implements the storage of AI/ML-driven recommendation deliveries as required for personalization, evidence tracking, and explainability (requirements sections 07 & 08).
///
/// Each record links a recommendation to a user and a product at a specific time, tracks which model/version served it, and whether the result was seen or acted upon. Maintains normalization by not pre-calculating favorites or analytics.
///
/// Key relationships: References {@link users.id} (who received), {@link products.id} (recommended content), and links to personalization events.
/// Special behaviors: Composite uniqueness for user, product, and timestamp (cannot re-recommend exact same thing at the same time), GIN index for rationale explainability/search.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model recommendations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique recommendation record.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. User receiving the recommendation.
  user_id String @db.Uuid

  /// Target product's {@link products.id}. Product being recommended.
  product_id String @db.Uuid

  /// AI model identifier generating the recommendation; for compliance and retrain audit.
  model_id String

  /// AI/ML model version generating this recommendation. Required for audit and transparency (regulatory).
  model_version String

  /// Optional human/machine-readable rationale, used for explainability and audit trail per compliance needs.
  rationale String?

  /// Timestamp when recommendation was delivered. Required for continuous feedback/monitoring.
  recommendation_time DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user    users    @relation(fields: [user_id], references: [id], onDelete: Cascade)
  product products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  personalization_events personalization_events[]
  personalization_audits personalization_audits[]

  @@unique([user_id, product_id, recommendation_time])
  @@index([product_id])
  @@index([recommendation_time])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Personalization Audit Table] - Implements the evidence-preserving audit log for all personalization and favorite-related actions, as required for regulatory, explainability, and continuous improvement needs (sections 07, 08, 09). 
///
/// Stores non-repudiable, immutable evidence for sensitive user actions related to favorites, bookmarks, recommendations, and AI-triggered changes. Maintains full normalization by referencing all participating entities and ensuring no pre-calculated or derived fields.
///
/// Key relationships: References {@link users.id}, {@link favorites.id}, {@link bookmarks.id}, {@link recommendations.id}, {@link personalization_events.id}. Cross-links actions for holistic compliance and model improvement.
/// Special behaviors: Write-once (append-only), cryptographically signed evidence, all fields atomic.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model personalization_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit record.
  id String @id @db.Uuid

  /// Belonged user's {@link users.id}. Links the personalization action to specific user.
  user_id String @db.Uuid

  /// Optional reference to {@link favorites.id}, maintained for evidence and retroactive compliance.
  favorite_id String? @db.Uuid

  /// Optional reference to {@link bookmarks.id}, maintained for evidence and retroactive compliance.
  bookmark_id String? @db.Uuid

  /// Optional reference to {@link recommendations.id}, to track audit events involving recommendations.
  recommendation_id String? @db.Uuid

  /// Optional link to {@link personalization_events.id}, audit evidence for anything with contextual event.
  personalization_event_id String? @db.Uuid

  /// Type/category of the audit event (e.g. ADD_FAVORITE, REMOVE_BOOKMARK, SERVE_RECOMMENDATION). Normalized/atomic for querying/compliance. For example: 'ACTIONS'.
  action_type String

  /// Cryptographic hash of the action/event for non-repudiation, as required for compliance.
  evidence_hash String

  /// Exact time of audit event for regulatory trace/compliance; enables reconstructing chain-of-custody.
  timestamp DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user                  users                   @relation(fields: [user_id], references: [id], onDelete: Cascade)
  favorite              favorites?              @relation(fields: [favorite_id], references: [id], onDelete: Cascade)
  bookmark              bookmarks?              @relation(fields: [bookmark_id], references: [id], onDelete: Cascade)
  recommendation        recommendations?        @relation(fields: [recommendation_id], references: [id], onDelete: Cascade)
  personalization_event personalization_events? @relation(fields: [personalization_event_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([favorite_id])
  @@index([bookmark_id])
  @@index([recommendation_id])
  @@index([personalization_event_id])
  @@index([timestamp])
  @@index([action_type(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-07-advanced_ai_operations.prisma:
/// AI Model Registry - This implements the requirement for a unified model registry and governance from section 08 (Advanced AI and Data Operations) of the requirements. 
///
/// Central repository for all AI/ML models used within the system, holding business metadata (name, description, model type, owner), categorization, and audit fields to enforce model governance, version tracking, and compliance. Maintains 3NF by not duplicating version, deployment, or decision info. For example, registering recommendation, dynamic pricing, or sentiment models. 
///
/// Key relationships: Connects with {@link ai_model_versions} for actual model instances, links to organizations and users for ownership, supports audit evidence. 
/// Special behaviors: Uniqueness constraint on (name, organization), all business fields are atomic and normalized.
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_models {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for each AI model.
  id String @id @db.Uuid

  /// Owning organization's {@link organizations.id} - Implements multidomain model governance requirement. Organization context for model accountability.
  organization_id String @db.Uuid

  /// Owning user's {@link users.id} - Maintains audit trace and role-based model management.
  owner_id String @db.Uuid

  /// Model name - Implements model identification aspect. Human-friendly, unique per organization. Prevents duplication, maintains normalization. Example: 'prod-recommendation-2024'
  name String

  /// Model type - Implements model taxonomy. Business meaning: e.g., recommendation, pricing, fraud. Ensures model classification is atomic. Example: 'recommendation'
  model_type String

  /// Description - Human-intelligible summary, implements evidence/traceability requirement. For example: 'Collaborative filtering model for top sellers'.
  description String?

  /// Creation timestamp - When model metadata was first registered. Atomic, not derived.
  created_at DateTime @db.Timestamptz

  /// Update timestamp - When model metadata was last changed. Ensures normalization. Example: model taxonomy change.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  organization organizations @relation(fields: [organization_id], references: [id], onDelete: Cascade)
  owner        users         @relation(fields: [owner_id], references: [id], onDelete: Cascade)

  ai_model_versions ai_model_versions[]
  ai_training_data  ai_training_data[]

  @@unique([organization_id, name])
  @@index([owner_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Model Versioning - Implements the requirement for full model lifecycle tracking and explainability from section 08 (Advanced AI and Data Operations) requirement.
///
/// Stores concrete versioned instances for each AI model, supporting lineage and deployment traceability. Complies with 3NF by never embedding decision or request data, only atomic version metadata. For example, each trained model artifact, versioned and ready for deployment or audit. 
///
/// Key relationships: Foreign key to {@link ai_models}, holds deployment metadata. Special behaviors: Unique constraint on (ai_model_id, version_hash).
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_model_versions {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for each model version.
  id String @id @db.Uuid

  /// Parent model's {@link ai_models.id} - Traces version lineage. Enforces normalization: no model metadata duplication.
  ai_model_id String @db.Uuid

  /// Version string - Implements versioning policy. e.g., 'v1.4.3', ensures atomicity, never derived. For tracking deployments.
  version String

  /// Version hash - Immutable hash of model artifact, supporting evidence preservation and integrity verification. For compliance (e.g. audit trails).
  version_hash String

  /// Artifact URI - Location of the model artifact in secure storage. Ensures normalization by referencing only, not storing contents.
  artifact_url String @db.VarChar(80000)

  /// ML framework - Business context: e.g., 'TensorFlow', 'PyTorch'. Maintains atomic, normalized record of build platform.
  framework String

  /// Version metadata - Implements evidence trace. JSON or key-value string for atomic version-specific fields (hyperparameters, notes). Never derived.
  metadata String?

  /// Creation timestamp - Atomic, when this version was created.
  created_at DateTime @db.Timestamptz

  /// Deployment timestamp - When this model version was deployed (if ever). Null if never deployed. Atomic. For regulatory/audit evidence.
  deployed_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  model ai_models @relation(fields: [ai_model_id], references: [id], onDelete: Cascade)

  review_sentiments       review_sentiments[]
  sentiment_analysis_logs sentiment_analysis_logs[]
  ai_feature_store        ai_feature_store[]
  ai_decision_logs        ai_decision_logs[]

  @@unique([ai_model_id, version_hash])
  @@index([ai_model_id])
}

/// AI Training Data Registry - Implements mandatory dataset tracking requirement from Advanced AI and Data Operations section.
///
/// Catalogs all datasets—internal or external—used in AI/ML training runs. Business purpose: ensuring evidence preservation, model governance, and regulatory compliance. 3NF maintained: no embedding feature or decision data, only atomic dataset metadata. For example, registering user purchase logs, product metadata, reviews, or imported partners' data feeds as AI input.
///
/// Key relationships: Models dataset-to-model and version relationships, supports traceability. Special behaviors: Uniqueness constraint on (name, version, source_uri).
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_training_data {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for training dataset.
  id String @id @db.Uuid

  /// Associated model's {@link ai_models.id} - Optional, as datasets may predate or span multiple models. Maintains traceable, normalized context.
  ai_model_id String? @db.Uuid

  /// Dataset name - Human-friendly identifier, e.g., '2024Q1-purchases'. Required. Normalization via uniqueness constraint with version+uri.
  name String

  /// Dataset version - e.g., 'v1', '202404', for traceability and reproducibility. Implements evidence requirement. Required.
  version String

  /// Source URI - Link to immutable, secured dataset in storage. Ensures data separation, not duplication. Required.
  source_uri String @db.VarChar(80000)

  /// Schema hash - Hash of dataset schema, for evidence and change detection. Ensures atomicity, never derived.
  schema_hash String

  /// Record count - Number of records/rows in the dataset. Atomic, reported only. Example: 10000000 (for 10M sale records).
  record_count Int? @db.Integer

  /// Creation timestamp - When dataset was first registered.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  model ai_models? @relation(fields: [ai_model_id], references: [id], onDelete: Cascade)

  ai_feature_store ai_feature_store[]

  @@unique([name, version, source_uri])
  @@index([ai_model_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Feature Store Registry - Implements the centralized feature tracking and evidence preservation requirement from the Advanced AI and Data Operations section.
///
/// Native registry for feature sets engineered for AI model training and inference. 3NF is ensured: field-level definitions of each feature set, no denormalization or pre-calculation. For example, storing user-product interaction feature set names, their schema description, and originating training dataset.
///
/// Key relationships: Links to {@link ai_training_data} (origin of features) and {@link ai_model_versions} (using version). Special behaviors: Uniqueness constraint on (ai_model_version_id, name).
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_feature_store {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for a feature set.
  id String @id @db.Uuid

  /// Target model version's {@link ai_model_versions.id} - Implements model lineage traceability requirement. Required.
  ai_model_version_id String @db.Uuid

  /// Source dataset's {@link ai_training_data.id} - Evidence link for feature extraction. Nullable, not all features require direct linkage. Maintains normalization.
  ai_training_data_id String? @db.Uuid

  /// Feature set name - Human-friendly label, e.g. 'user-purchase-matrix-v1'. Normalized and unique per model version. Example: 'sentiment-review-set-202404'.
  name String

  /// Description - Detailed documentation for audit/compliance. Evidence trace for explainability. Example: 'Features for collaborative filtering.'
  description String?

  /// Feature schema - Machine-readable JSON schema representing the feature set structure. Maintains normalization; no denormalized data here.
  schema String

  /// Creation timestamp - Evidence of when engineering completed.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  model_version ai_model_versions @relation(fields: [ai_model_version_id], references: [id], onDelete: Cascade)
  training_data ai_training_data? @relation(fields: [ai_training_data_id], references: [id], onDelete: Cascade)

  @@unique([ai_model_version_id, name])
  @@index([ai_training_data_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Decision Log - Implements mandatory logging and explainability requirement from Advanced AI and Data Operations section.
///
/// Immutable, atomic record of each automated decision or inference by any AI model. Business purpose: evidence for compliance (GDPR 'right to explanation'), debugging, monitoring, and model improvement. Keeps schema atomic: never stores denormalized or summarized results, only per-decision facts and links. For example, logging a recommendation output for a specific user or order.
///
/// Key relationships: References {@link ai_model_version}, target entity (user, product, order, etc.), audit details. Special behaviors: Enforces data provenance via foreign keys and immutable timestamps.
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_decision_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for a decision log.
  id String @id @db.Uuid

  /// Associated model version's {@link ai_model_versions.id} - Tracks which version produced this decision. Required.
  ai_model_version_id String @db.Uuid

  /// Target user's {@link users.id} - The user affected by decision. Nullable where not user-specific. Maintains normalization, never derived.
  target_user_id String? @db.Uuid

  /// Target entity - Implements audit tracking of affected object. E.g., 'order', 'product', 'review'. Prevents denormalization by not embedding entity fields.
  target_entity String

  /// Target entity ID - The ID of the affected object (atomic, never joined/duplicated), e.g. product or order ID. Maintains strict normalization.
  target_entity_id String @db.Uuid

  /// Decision outcome - E.g., 'recommend', 'block', 'price=12.50'. Business context: ensures traceability, atomicity, never computed. For model explainability.
  decision String

  /// Input snapshot - JSON or base64 blob representing the exact input to the AI at inference, for audit and debugging. 3NF: atomic per event.
  input_snapshot String

  /// Model rationale - Explanation for the decision, if available. Supports compliance, 3NF, and human override/audit.
  rationale String?

  /// Timestamp of decision event for audit/evidence.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  model_version ai_model_versions @relation(fields: [ai_model_version_id], references: [id], onDelete: Cascade)
  target_user   users?            @relation(fields: [target_user_id], references: [id], onDelete: Cascade)

  ai_feedback ai_feedback[]

  @@index([ai_model_version_id])
  @@index([target_user_id])
  @@index([target_entity, target_entity_id])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// AI Feedback Log - Implements feedback loop requirement for continuous learning and audit from Advanced AI and Data Operations section.
///
/// Stores explicit and implicit feedback for each AI decision event, connecting user actions or operator overrides to the original model inference. Enables automated model retraining, human override validation, and explainability for regulators. 3NF strict: each field atomic, all links explicit, no denormalization.
///
/// Key relationships: Links {@link ai_decision_logs} (original decision), user, and model version. Special behaviors: Composite index on (decision_log_id, user_id, feedback_type).
///
/// @namespace AdvancedAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_feedback {
  //----
  // COLUMNS
  //----
  /// Primary Key - Unique identifier for feedback event.
  id String @id @db.Uuid

  /// Original decision log's {@link ai_decision_logs.id} - Implements feedback-data linkage for model retraining. Required.
  decision_log_id String @db.Uuid

  /// User's {@link users.id} submitting feedback or being observed for implicit signals. Allows anonymous/null for auto signals.
  user_id String? @db.Uuid

  /// Type of feedback - E.g., 'accepted', 'dismissed', 'overridden', 'implicit-click'. Atomic per event. Implements feedback/data tracking requirement.
  feedback_type String

  /// Feedback value - E.g., 'positive', 'negative', 'rating=5'. Business context: for retraining, analysis. Strictly atomic, not computed.
  feedback_value String?

  /// Metadata - (Optional) JSON/string with UI context, device info, or feedback rationale. Atomic/non-derived, supports explainability.
  metadata String?

  /// Timestamp of feedback event. Maintains evidence, not derived.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  decision_log ai_decision_logs @relation(fields: [decision_log_id], references: [id], onDelete: Cascade)
  user         users?           @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([decision_log_id, user_id, feedback_type])
}

schemas.schema-08-security_compliance.prisma:
/// Security Event Logging - This implements event logging and evidence preservation for all security-relevant actions as per Section 2 (Critical Data Auditing) and Section 4 (Data Integrity & Preservation) of the requirements. 
///
/// Records all system-level security-related occurrences, capturing actor, context, and timestamp for each. Maintains 3NF by storing only atomic event-level data and referencing origin entities via foreign keys. For example, an API token rotation, a failed login attempt, or privilege escalation. Key relationships: links to relevant user, session, and API client where applicable. Special behaviors: immutable; no deletion, supports audit retrieval.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model security_event {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each security event record.
  id String @id @db.Uuid

  /// Reference to initiating user's {@link users.id}. If system-initiated, can be null. Ensures mapping of event context to user for audit.
  user_id String? @db.Uuid

  /// Associated session {@link sessions.id}. Links actions to active session for traceability.
  session_id String? @db.Uuid

  /// API client context {@link api_clients.id} under which the event occurred, if relevant.
  api_client_id String? @db.Uuid

  /// Category of security event (e.g., 'login_attempt', 'token_rotation', 'permission_update') - Implements Section 2 (Critical Data Auditing). Encodes nature of event for context-rich evidence. For example, used for analytics and compliance dashboards. Required.
  event_type String

  /// Human- and machine-readable details of the event - Implements evidence preservation requirement. Provides business context; can include affected fields, prior values, or policy triggers. For example, stores JSON stringified details. Required.
  event_details String

  /// Creation timestamp of the event record - Ensures non-repudiation as required for audit trails and regulatory compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user       users?       @relation(fields: [user_id], references: [id], onDelete: Cascade)
  session    sessions?    @relation(fields: [session_id], references: [id], onDelete: Cascade)
  api_client api_clients? @relation(fields: [api_client_id], references: [id], onDelete: Cascade)

  @@index([session_id])
  @@index([api_client_id])
  @@index([user_id, created_at])
  @@index([event_type, created_at])
}

/// Permission Registry - This implements dynamic and fine-grained permission tracking aligned to Section 3 (Access Control & Permission). 
///
/// Tracks all permissions available in the platform, with atomic records for each permission entity. 3NF maintained: only basic attributes and references to associated policy. For example, permissions like 'order.edit', 'discount.apply'. Key relationships: can be referenced in policy and role mappings. Special behaviors: unique codes enforced, never deleted (for historical policy linkage).
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model permission {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for permission.
  id String @id @db.Uuid

  /// Associated policy's {@link policy.id}. Connects permission entity to rules and conditions applying to it.
  policy_id String? @db.Uuid

  /// Unique permission code (e.g., 'user.read', 'order.cancel') - Implements fine-grained access control as required by Section 3. For example, used in runtime permission checks. Must be unique across system. Required.
  code String

  /// Detailed description of what the permission entails - Maps to regulatory and explainability requirements. For example, describes business context for UI and audit tools. Required.
  description String

  /// Timestamp of permission creation - For audit and evidence preservation as per requirements.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  policy policy? @relation(fields: [policy_id], references: [id], onDelete: Cascade)

  @@unique([code])
  @@index([policy_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Permission Policy - This model implements Section 3 and 5 (dynamic policy-driven permission enforcement, regulatory compliance tracking). 
///
/// Represents a logical grouping of permissions with optional conditions or constraints. Maintains 3NF by storing only atomic policy-level data. For example, policies for 'admin_only', time-bound permissions, region-limited access. Key relationships: can be referenced by permissions, roles, or external API modules. Special behaviors: policies remain after deletion for legal traceability.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model policy {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a policy.
  id String @id @db.Uuid

  /// Human-readable policy name - Implements requirement for business logic explainability and traceability. For example, 'Admin Global', 'EU Data Export'. Required.
  name String

  /// Serialized JSON or code describing policy constraints/logic - Aligns with dynamic enforcement and compliance. For example, specifies conditions such as 'only during office hours'. Required.
  conditions String

  /// Creation timestamp for policy record - Provides evidence trail needed for audits. Required.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  permission permission[]

  @@unique([name])
  @@index([conditions(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Audit Log - Implements end-to-end non-repudiable logging for all system and user actions, in accordance with Section 4 and 5 (Data Integrity, Evidence, Audit-Ready Structure). 
///
/// Stores immutable audit records for every critical operation and event. 3NF achieved by isolating raw events with user, entity, and context references. Used for regulatory export, legal inquiry, and breach forensics. Key relationships: links to user, affected entity (as foreign key where possible), evidence_archive. Special behaviors: append-only; deletion prohibited.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model audit_log {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit log record identifier.
  id String @id @db.Uuid

  /// User actor responsible for action {@link users.id}. Enables user-centric audit filtering for compliance exports.
  user_id String? @db.Uuid

  /// Archived evidence snapshot {@link evidence_archive.id} associated with event.
  evidence_archive_id String? @db.Uuid

  /// Type of action performed (e.g., 'create', 'update', 'delete', 'payment.approve') - Implements requirement for business trace and explainability. For example, facilitates compliance dashboard queries. Required.
  action String

  /// Type of entity affected (e.g., 'order', 'user', 'review') - Enables entity-level filtering and integrity checks. Required.
  entity_type String

  /// ID of the affected entity instance - Ensures traceability down to individual records, fulfilling audit trail requirements. Nullable for system events not targeting specific entity.
  entity_id String? @db.Uuid

  /// JSON-encoded metadata/context of the audit event - Supports regulatory and forensics use. For example, before/after data, machine/environmental context. Required.
  context String

  /// Timestamp of audit log creation - For evidence and compliance enforcement. Required.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user             users?            @relation(fields: [user_id], references: [id], onDelete: Cascade)
  evidence_archive evidence_archive? @relation(fields: [evidence_archive_id], references: [id], onDelete: Cascade)

  @@index([evidence_archive_id])
  @@index([user_id, created_at])
  @@index([entity_type, entity_id, created_at])
}

/// Compliance Report - This table fulfills Section 5 requirements for regulatory export, oversight, and drilldown on AI-driven or security events. 
///
/// Stores generated compliance reports (GDPR, CCPA, internal regs) and their metadata. Maintains 3NF by only referencing report owner/user, storing atomic report attributes. For example, a GDPR export delivered to a user, or a monthly payment compliance summary. Key relationships: owners (user, organization), linked evidence. Special behaviors: cannot be edited once published, may be superseded by later reports.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model compliance_report {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique compliance report identifier.
  id String @id @db.Uuid

  /// Owner or data subject {@link users.id} for individual reports.
  user_id String? @db.Uuid

  /// Owning organization {@link organizations.id}, if applicable.
  organization_id String? @db.Uuid

  /// Classification of compliance report (e.g., 'GDPR_EXPORT', 'CCPA_AUDIT') - Implements export and oversight requirements. Required.
  report_type String

  /// Status of report (e.g., 'pending', 'published', 'superseded') - Ensures auditability of report progression. For example, status visible in admin dashboards. Required.
  status String

  /// Timestamp when report was generated - For audit and tracking as per requirements. Required.
  generated_at DateTime @db.Timestamptz

  /// Timestamp when report was published/delivered; required for evidence trail and deadline compliance. Nullable if not yet published.
  published_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user         users?         @relation(fields: [user_id], references: [id], onDelete: Cascade)
  organization organizations? @relation(fields: [organization_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([organization_id])
  @@index([report_type, generated_at])
}

/// Data Retention Policy - This implements configurable data retention, deletion, and legal hold logic (Section 5), supporting entity-level configurations and traceability.
///
/// Stores data retention policy per data subject or entity. 3NF maintained by separating atomic policy settings per record. For example, policies for user data, payment log, or review. Key relationships: can be linked to entity, organization, user for context. Special behaviors: enforced by backend logic, referenced by compliance_report, deletion must leave audit trace.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model data_retention {
  //----
  // COLUMNS
  //----
  /// Primary Key for data_retention policy record.
  id String @id @db.Uuid

  /// Organization to which retention policy applies {@link organizations.id}. Enables B2B use cases and regulatory separation.
  organization_id String? @db.Uuid

  /// Entity data type subject to retention policy (e.g., 'user', 'order', 'review') - Aligns with regulatory entity-level retention needs. Required.
  entity_type String

  /// Retention period in days (e.g., 365, 1095) - Ensures compliance with regulatory and contract requirements. For example, controls automated deletion logic. Required.
  retention_period_days Int @db.Integer

  /// Legal hold status - Implements requirement for holding deletion in progress during litigation/audit. For example, backend logic enforces this. Required.
  is_legal_hold Boolean

  /// Policy record creation time - Fulfills requirement for audit trail per policy change. Required.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  organization organizations? @relation(fields: [organization_id], references: [id], onDelete: Cascade)

  @@unique([entity_type, organization_id])
  @@index([organization_id])
}

/// Evidence Archive - Implements immutable, compressed archiving for critical evidence as required in Section 4 (Evidence Preservation) and Section 5 (Compliance). 
///
/// Stores compressed or signed evidence payloads for system operations, enabling legal, forensics, and audit exports. 3NF enforced by separating blob storage and atomic references. For example, a zipped export of user data provided for GDPR DSAR; a signed PDF of payment logs. Key relationships: referenced in audit_log, compliance_report, and other tables where evidence may be required. Special behaviors: blob/blob reference is immutable and append-only; cannot be deleted, only superseded.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model evidence_archive {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique evidence archive record identifier.
  id String @id @db.Uuid

  /// Type/category of archived evidence (e.g., 'GDPR_DSAR_EXPORT', 'PAYMENT_LOG_SNAPSHOT') - Fulfilling evidence preservation and compliance needs. Required.
  evidence_type String

  /// URI for archived evidence binary/payload - Implements requirement for logical separation of data and reference. For example, S3/GCS/Blob Storage link. Required.
  blob_url String @db.VarChar(80000)

  /// Size of the archived evidence in bytes - For audit, integrity, and storage cost assessment. Fulfills traceability requirements. Required.
  size_bytes Int @db.Integer

  /// Cryptographic hash (e.g., SHA256) for the stored evidence - Implements data integrity and non-repudiation patterns. Required.
  checksum String

  /// Timestamp of evidence creation/archival. Supports evidence chain enforcement. Required.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  audit_log audit_log[]

  @@index([created_at])
  @@index([checksum(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-09-api_omnichannel.prisma:
/// [API Client Registry] - This implements the client registration and management requirement for API and omnichannel extensibility from the scalability and integration section of the requirements. 
///
/// Business explanation: Represents all third-party, partner, or internal software clients authorized to interact with the platform via APIs or omnichannel connectors. Maintains 3NF compliance by only storing atomic client metadata and security configuration, with all usage/interaction history managed in separate audit/sessions models. For example, a registered ERP partner system or mobile app client would have an instance here.
///
/// Key relationships: Connected to API tokens (for issued secrets), audit logs (for operations), and integration channels (for channel associations).
/// Special behaviors: Certificate/public-key fields, client revocation and expiration, and strict uniqueness on client_name.
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model api_clients {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [Client Name] - Implements the requirement for unique human-readable identification of the API/omnichannel client. 
  ///
  /// Used for admin UI and logging, not as technical credential. Ensures normalization by separating identity from secrets. Example: 'Acme ERP Gateway'.
  client_name String

  /// [Description] - Brief business description of client/app integration. 
  ///
  /// For admins, auditability, and risk/compliance review. Atomic string for documentation. Example: 'Official mobile application for end-users.'
  description String?

  /// [Contact Email] - Administrative contact for support/issues. 
  ///
  /// Used for notifications, incident response. Not a user reference. Atomic and unique per client. Example: 'devops@partner.com'.
  contact_email String

  /// [Public Key or Certificate] - Implements the API client verification requirement for secure request signing, especially for B2B/integrated clients. 
  ///
  /// Stored as text blob. No duplication or relational data. Example: PEM key/certificate.
  public_key String?

  /// [Activation Status] - Is this API client currently permitted to call APIs/integrations? 
  ///
  /// Implements the enable/disable for operational security and access controls. Not derived, not transitive. Example: Initially true upon onboarding.
  is_active Boolean

  /// [Creation Timestamp] - When this client entry was registered. 
  ///
  /// Evidence for audit, onboarding, and rotation policies. Atomic timestamp.
  created_at DateTime @db.Timestamptz

  /// [Revocation (Soft Delete) Timestamp] - When this client integration was revoked, decommissioned, or scheduled for archival. 
  ///
  /// Evidence for audit/forensics. Soft delete pattern.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  security_event security_event[]
  api_tokens     api_tokens[]
  api_audits     api_audits[]

  @@unique([client_name])
  @@index([is_active])
}

/// [API Access Token] - This implements the secure API authentication/authorization requirement, tracking all issued credentials for API and integration client access, mapped to requirements for token lifecycle management and security event monitoring. 
///
/// Business explanation: Stores all tokens/secrets granted to a specific API client. Maintains 3NF: token value, issued scope, and expiry are atomic, with usage logs and audit in secondary tables. For example, an OAuth2/JWT token for Acme's integration client. 
///
/// Key relationships: Linked to api_clients, with cascaded deletion/invalidation support. 
/// Special behaviors: Token revocation, rotation, scope definition, expiry, and linkage to session and audit models.
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model api_tokens {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [API Client Reference] - Belonged API client's {@link api_clients.id}. 
  ///
  /// Links the token to its registered client application for evidence and access validation.
  api_client_id String @db.Uuid

  /// [Token Value] - Implements requirement to securely store issued access token (hashed/encrypted). 
  ///
  /// Atomic (not derived), never duplicated in plain text. Example: Hashed OAuth2 JWT or custom token.
  token_value String

  /// [Token Scope] - Business/technical permission associated with this token. 
  ///
  /// Stored as delimited/structured string for 3NF. Example: 'read:orders,write:catalog'.
  scope String

  /// [Token Issued At] - Timestamp of when the token was created/granted. 
  ///
  /// Strict evidence and compliance requirement.
  issued_at DateTime @db.Timestamptz

  /// [Token Expiry] - When this access credential will expire, per business security/compliance rules. 
  ///
  /// Atomic timestamp value. For example, 7 days from issue.
  expires_at DateTime @db.Timestamptz

  /// [Token Revocation Timestamp] - If/when this token was manually invalidated, for incident response or admin action. 
  ///
  /// Soft delete pattern, atomic value.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  client api_clients @relation(fields: [api_client_id], references: [id], onDelete: Cascade)

  api_audits       api_audits[]
  channel_sessions channel_sessions[]

  @@unique([token_value])
  @@index([api_client_id])
  @@index([expires_at])
}

/// [API Audit Trail] - Implements the requirement for comprehensive evidence logging and traceability of all API/omnichannel activity for compliance, security, forensics, and analytics. 
///
/// Business explanation: Stores each API request/event record, including actor, endpoint, action, decision logic, input/output hashes and outcomes. Strictly normalized: each row is atomic, no aggregates or summaries. Used to reconstruct incident timelines, regulatory reviews, or AI feedback for model retraining. For example, logging a PATCH to order status API or a failed webhook delivery. 
///
/// Key relationships: Linked to api_clients, api_tokens, and integration_channels (omnichannel source). 
/// Special behaviors: No deletion; retention policy and evidence archiving instead.
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model api_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [API Client Reference] - Belonged API client from {@link api_clients.id}. 
  ///
  /// Source of the request/session/event.
  api_client_id String @db.Uuid

  /// [API Token Reference] - Credential used for this operation, {@link api_tokens.id}. 
  ///
  /// Enables evidence mapping, forensics, and access validation.
  api_token_id String @db.Uuid

  /// [Integration Channel Reference] - Omnichannel source of request/event {@link integration_channels.id}. 
  ///
  /// E.g., 'web', 'mobileapp', 'partner_erp'.
  integration_channel_id String? @db.Uuid

  /// [API Endpoint Path] - Implements requirement for full request path traceability. 
  ///
  /// Atomic path string, e.g. '/v2/order/{id}/update'.
  endpoint String

  /// [HTTP Method] - Captures action type for compliance ('GET', 'POST', etc.). 
  ///
  /// Atomic, not derived. Example: 'POST'.
  http_method String

  /// [Actor/Subject ID] - UUID of user/service/entity causing action. 
  ///
  /// Atomic reference. May reference user, partner, or system actor.
  actor_id String @db.Uuid

  /// [AI Decision Log Reference] - If this API operation involved an automated/AI-based decision, reference unique log id. 
  ///
  /// Supports explainability, model audit. May be nullable for non-AI flows.
  decision_log_id String? @db.Uuid

  /// [Request Body Hash] - Deterministic hash of input payload for integrity/evidence preservation. 
  ///
  /// Prevents tampering. Atomic value, e.g. sha256(data).
  request_hash String

  /// [Response Body Hash] - Deterministic hash of returned payload for end-to-end evidence/auditing. 
  ///
  /// Anti-tampering.
  response_hash String

  /// [Success Flag] - Was this operation permitted/executed? 
  ///
  /// For real-world forensics/audit, not derived. Atomic.
  is_success Boolean

  /// [HTTP Status Code] - Final status from this request. 
  ///
  /// Atomic integer. Example: 200, 401, 500.
  status_code Int @db.Integer

  /// [Request Timestamp] - Time request was received and logged. 
  ///
  /// Atomic timestamp for compliance and audit.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  client              api_clients           @relation(fields: [api_client_id], references: [id], onDelete: Cascade)
  token               api_tokens            @relation(fields: [api_token_id], references: [id], onDelete: Cascade)
  integration_channel integration_channels? @relation(fields: [integration_channel_id], references: [id], onDelete: Cascade)

  @@index([api_token_id])
  @@index([integration_channel_id])
  @@index([api_client_id, created_at])
  @@index([endpoint, created_at])
}

/// [Integration Channel] - Implements the requirement to support omnichannel sources/connections and API gateways from the scalability and extensibility module. 
///
/// Business explanation: Each record represents an authorized source channel (e.g., web, mobile, external ERP, partner API gateway) that can initiate or receive events/integrations. Maintains 3NF and normalization: does not duplicate client/channel config, but links to associated sessions, audits, and webhooks. For example, a 'Point-of-Sale Kiosk' integration or a 'Partner CRM'. 
///
/// Key relationships: Referenced by channel_sessions, audits, and used for system events/analytics.
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model integration_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [Channel Code] - Unique technical identifier for the source/integration channel. 
  ///
  /// Required for business logic, routing, and automation. Example: 'mobileapp', 'partner_erp'.
  channel_code String

  /// [Channel Name] - Human readable, unique/channel-scoped label for easier management. 
  ///
  /// Not a code/slug. Example: 'Main Web Storefront'.
  channel_name String

  /// [Activation Status] - Indicates if the channel is currently enabled for communication and integrations. 
  ///
  /// Atomic, not derived. For compliance and automation.
  is_active Boolean

  /// [Registration Timestamp] - Channel setup/registration time for system auditability. 
  ///
  /// Atomic timestamp. For evidence and analytics.
  created_at DateTime @db.Timestamptz

  /// [Deactivation (Soft Delete) Timestamp] - When this integration was formally ended (for audit/compliance). 
  ///
  /// Implements soft delete pattern. Atomic timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  api_audits       api_audits[]
  channel_sessions channel_sessions[]
  webhook_events   webhook_events[]

  @@unique([channel_code])
  @@index([is_active])
}

/// [Channel Session/Instance] - Implements omnichannel session/lifecycle evidence for concurrent usage, device mapping, and scalability analysis, mapped to the requirement for cross-channel tracking and analytics. 
///
/// Business explanation: Each row represents a single connection period/session for a user/client/channel combination (e.g., a POS login, or mobile session). Restricts attributes to atomic values—expirations, tokens, associated references. For example, a customer on the web channel, switching to mobile with the same cart/order context.
///
/// Key relationships: Linked to integration_channels, api_tokens, and used for session state analytics.
/// Special behaviors: Session expiration/invalidations. All denormalized summaries go to mv_ tables only.
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model channel_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [Integration Channel Reference] - Channel for this session, {@link integration_channels.id}. 
  ///
  /// Atomic; no duplicates.
  integration_channel_id String @db.Uuid

  /// [API Token Reference] - Access token that initiated this session {@link api_tokens.id}. 
  ///
  /// Atomic; session always requires a token.
  api_token_id String @db.Uuid

  /// [User Reference] - Optional user UUID linked to this session. 
  ///
  /// When present, identifies the direct user; otherwise, may be system/integration. Example: buyer channel login, or anonymous device.
  user_id String? @db.Uuid

  /// [Session Key] - System-generated, opaque identifier for this channel session instance. 
  ///
  /// Atomic string, for referencing in logs or context-passing APIs.
  session_key String

  /// [Started At Timestamp] - When this channel session began. 
  ///
  /// Exact audit evidence, for compliance and automation.
  started_at DateTime @db.Timestamptz

  /// [Ended At Timestamp] - When session was terminated (timeout, logout). 
  ///
  /// Not derived. Null if still open.
  ended_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  integration_channel integration_channels @relation(fields: [integration_channel_id], references: [id], onDelete: Cascade)
  api_token           api_tokens           @relation(fields: [api_token_id], references: [id], onDelete: Cascade)

  @@unique([session_key])
  @@index([api_token_id])
  @@index([started_at])
  @@index([integration_channel_id, started_at])
}

/// [Webhook Event/Notification] - Implements the external/internal event delivery and audit requirements for extensible integration, system notification, and partner automation. 
///
/// Business explanation: Captures each system or API-originated webhook event, including delivery state and evidence for retries/audits. Fully normalized—relationship to originating channel, destination, and technical params only (payloads not stored here, only hashes/IDs). For example, a notification to a partner when an order is updated, or price changes via API. 
///
/// Key relationships: Linked to integration_channels. Used for compliance, analytics, and incident response.
/// Special behaviors: Delivery tracking, retry evidence, event outcome codification, no denormalization (all summaries are in mv_ tables only).
///
/// @namespace API_Omnichannel
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model webhook_events {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// [Integration Channel Reference] - Channel that originated/scheduled the webhook {@link integration_channels.id}. 
  ///
  /// Atomic for audit, routing, compliance.
  integration_channel_id String @db.Uuid

  /// [Event Type] - Business/technical event code (e.g., 'order.updated', 'payment.completed'). 
  ///
  /// Atomic, not derived. For routing and compliance purposes.
  event_type String

  /// [Destination URL] - Target endpoint for webhook delivery. 
  ///
  /// Atomic and unique per webhook. Never duplicated. Example: 'https://partner.com/hook'.
