   * unique in combination with version and source_uri. Enables clear
   * identification in audit logs, reporting, and ML/analytics UI.
   */
  name: string;

  /**
   * Version identifier (e.g., 'v1', '202404'). Required to distinguish
   * individual dataset versions for reproducibility, evidence trace, and
   * compliance.
   */
  version: string;

  /**
   * URI to the immutable source dataset (e.g., S3, GCS, file path). Required
   * for provenance, legal/regulatory audits, and supporting data
   * reproducibility in ML.
   */
  source_uri: string;

  /**
   * Cryptographic hash of the dataset schema used for integrity, provenance,
   * and regulatory proof of structure. Aids in detecting dataset drift,
   * tampering, or schema upgrades.
